window.ANSWER_TERMS = {"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"microtubuli":{"title":"Microtubuli","short":"Holle buisjes van tubuline; het stevigste onderdeel van het cytoskelet, sporen voor transport en de mitosespoel.","definition":"<p><b>Microtubuli</b> zijn holle buisjes opgebouwd uit tubuline-dimeren. Ze zijn dynamisch: ze groeien en krimpen aan hun uiteinden.</p><p>Ze geven de cel structuur, vormen de rails voor de motoreiwitten kinesine en dyneïne, en bouwen tijdens de celdeling de mitosespoel.</p>","image_url":"","wiki_title":"Microtubule","match":"microtubuli|microtubulus"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"covid-19":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"covid-19|covid|sars-cov-2|corona","option_only":true},"quetiapine":{"title":"Quetiapine","short":"Quetiapine is een atypisch antipsychoticum dat vooral sederend werkt; gebruikt bij psychose, bipolaire stoornis en soms bij onrust.","definition":"<p><strong>Quetiapine</strong> is een <em>atypisch (tweede generatie) antipsychoticum</em>. Het blokkeert dopamine-D2- en serotonine-5-HT2A-receptoren, en daarnaast sterk histamine-H1- en α1-receptoren.</p><p>Daardoor werkt het duidelijk sederend en geeft het weinig extrapiramidale bijwerkingen. Indicaties: schizofrenie, bipolaire stoornis (manie en depressie). Bijwerkingen: sufheid, orthostatische hypotensie, gewichtstoename en metabole ontregeling.</p>","image_url":"","wiki_title":"Quetiapine","match":"quetiapine","option_only":true},"serotonine":{"title":"Serotonine","short":"Serotonine (5-HT) is een monoamine uit tryptofaan; neurotransmitter voor stemming, slaap en eetlust en in de darm en bloedplaatjes actief.","definition":"<p><strong>Serotonine</strong> (5-hydroxytryptamine) wordt gemaakt uit het aminozuur <em>tryptofaan</em>. Het meeste zit in enterochromaffiene cellen van de darm en wordt in bloedplaatjes opgeslagen.</p><p>In het brein komen serotonerge neuronen uit de raphekernen van de hersenstam; ze beïnvloeden stemming, angst, slaap, eetlust en pijn. SSRI's remmen de heropname en worden bij depressie en angststoornissen gebruikt. In de darm stimuleert serotonine de motiliteit; perifeer veroorzaakt het vasoconstrictie of -dilatatie afhankelijk van het vaatbed.</p>","image_url":"","wiki_title":"Serotonin","match":"serotonine|5-ht|5-hydroxytryptamine|serotonin","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"hersenstam":{"title":"Hersenstam","short":"De hersenstam (mesencephalon, pons, medulla oblongata) verbindt grote hersenen en ruggenmerg en bevat kernen van hersenzenuwen en centra voor ademhaling en circulatie.","definition":"<p>De <strong>hersenstam</strong> bestaat uit het mesencephalon (middenhersenen), de pons en de medulla oblongata. Alle opstijgende en afdalende banen tussen hersenen en ruggenmerg lopen erdoorheen.</p><p>Hij bevat de kernen van de hersenzenuwen III–XII, de formatio reticularis (bewustzijn, slaap-waakritme) en vitale centra voor ademhaling en hart- en vaatregulatie. Uitval van de hersenstam is daardoor snel levensbedreigend; hersenstamreflexen worden getest bij de vaststelling van hersendood.</p>","image_url":"","wiki_title":"Brainstem","match":"hersenstam|truncus cerebri|truncus encephali","option_only":true},"hypothalamus":{"title":"Hypothalamus","short":"De hypothalamus is het regelcentrum van de homeostase: hij stuurt hypofyse, autonoom zenuwstelsel, temperatuur, honger, dorst en circadiaan ritme.","definition":"<p>De <strong>hypothalamus</strong> is een klein deel van het diencephalon, onder de thalamus en rond de derde ventrikel. Hij is via het infundibulum verbonden met de hypofyse.</p><p>Hij maakt releasing- en inhibiting-hormonen (o.a. TRH, CRH, GnRH, GHRH, dopamine) die via het portale systeem de voorkwab sturen, en ADH en oxytocine die in de achterkwab worden afgegeven. Daarnaast regelt hij lichaamstemperatuur, honger en verzadiging, dorst, het slaap-waakritme (nucleus suprachiasmaticus) en het autonome zenuwstelsel.</p>","image_url":"","wiki_title":"Hypothalamus","match":"hypothalamus","option_only":true},"thalamus":{"title":"Thalamus","short":"De thalamus is het grote schakelstation in het diencephalon: vrijwel alle sensorische informatie (behalve reuk) wordt hier verwerkt op weg naar de cortex.","definition":"<p>De <strong>thalamus</strong> is een paarige, eivormige kern in het diencephalon aan weerszijden van de derde ventrikel. Hij bestaat uit veel subkernen met elk een eigen corticale projectie.</p><p>Sensorische banen (somatosensoriek via de VPL/VPM, zien via het corpus geniculatum laterale, horen via het corpus geniculatum mediale) schakelen hier om naar de cortex. Ook motorische lussen van basale kernen en cerebellum lopen via de thalamus, en hij speelt een rol bij bewustzijn en aandacht.</p>","image_url":"","wiki_title":"Thalamus","match":"thalamus","option_only":true},"globus pallidus pars externa":{"title":"Globus pallidus pars externa (GPe)","short":"De GPe is onderdeel van de basale kernen en vormt een schakel in de indirecte route; hij remt de nucleus subthalamicus.","definition":"<p>De <strong>globus pallidus pars externa</strong> is het laterale deel van de globus pallidus. Hij ontvangt remmende (GABA-erge) input van het striatum en stuurt zelf remmende projecties naar de nucleus subthalamicus.</p><p>Hij is een kernschakel van de <em>indirecte route</em> van de basale kernen (cortex → striatum → GPe → nucleus subthalamicus → GPi/SNr → thalamus), die beweging per saldo afremt.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus pars externa|gpe|globus pallidus externus|globus pallidus externa","option_only":true},"globus pallidus pars interna":{"title":"Globus pallidus pars interna (GPi)","short":"De GPi is de belangrijkste uitgangskern van de basale kernen; hij remt (GABA-erg) de motorische thalamus.","definition":"<p>De <strong>globus pallidus pars interna</strong> is samen met de substantia nigra pars reticulata de <em>uitgangskern</em> van de basale kernen. Hij geeft tonisch remmende GABA-erge output naar de motorische kernen van de thalamus.</p><p>De directe route (striatum → GPi) remt de GPi en ontremt zo de thalamus (meer beweging); de indirecte route versterkt via de nucleus subthalamicus juist de remming. De GPi is een doelwit bij diepe hersenstimulatie (o.a. dystonie, Parkinson).</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus pars interna|gpi|globus pallidus internus|globus pallidus interna","option_only":true},"nucleus subthalamicus":{"title":"Nucleus subthalamicus","short":"De nucleus subthalamicus is een exciterende (glutamaterge) kern van de basale kernen in de indirecte route; laesie geeft hemiballisme.","definition":"<p>De <strong>nucleus subthalamicus</strong> ligt onder de thalamus, boven de substantia nigra. Het is de enige <em>exciterende</em> (glutamaterge) kern van de basale kernen.</p><p>Hij ontvangt remmende input van de GPe en prikkelt de GPi en substantia nigra pars reticulata, waardoor de thalamus sterker geremd wordt (indirecte route). Een laesie (bijv. een lacunair infarct) geeft contralateraal <em>hemiballisme</em>. Het is ook een doelwit voor diepe hersenstimulatie bij de ziekte van Parkinson.</p>","image_url":"","wiki_title":"Subthalamic nucleus","match":"nucleus subthalamicus|stn|subthalamische kern","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"epilepsie":{"title":"Epilepsie","short":"Epilepsie is een hersenaandoening met herhaalde, niet-uitgelokte epileptische aanvallen door abnormale, synchrone ontladingen van neuronen.","definition":"<p>Bij <strong>epilepsie</strong> heeft iemand de neiging tot herhaalde epileptische aanvallen. Een aanval ontstaat door een plotselinge, overmatige en gesynchroniseerde ontlading van groepen neuronen.</p><p>Aanvallen kunnen focaal beginnen (in één hersengebied; met of zonder bewustzijnsdaling) of gegeneraliseerd (beide hemisferen; bijv. tonisch-klonische aanvallen of absences). Oorzaken: genetisch, structureel (litteken, tumor, ontwikkelingsstoornis), infectieus, metabool of onbekend. Diagnostiek met anamnese/heteroanamnese, EEG en MRI.</p>","image_url":"","wiki_title":"Epilepsy","match":"epilepsie","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"samenvatten":{"title":"Samenvatten (gesprekstechniek)","short":"Samenvatten is een gesprekstechniek waarbij de arts de kern van wat de patiënt heeft verteld kort in eigen woorden teruggeeft, om te checken en te structureren.","definition":"<p>Bij <strong>samenvatten</strong> vat de arts meerdere uitspraken of een heel gespreksdeel van de patiënt kort samen. Het doel is te controleren of de informatie goed begrepen is, overzicht te geven en het gesprek te structureren, bijvoorbeeld als afsluiting van een fase voordat een nieuw onderwerp begint.</p><p>Samenvatten gaat over de inhoud van een groter deel van het gesprek; het verschilt daarin van parafraseren, dat één uitspraak teruggeeft.</p>","image_url":"","wiki_title":"","match":"samenvatten|samenvatting geven","option_only":true},"illusionaire vervalsing":{"title":"Illusionaire vervalsing","short":"Een illusionaire vervalsing (illusie) is het verkeerd waarnemen van een werkelijk bestaande prikkel, bijvoorbeeld een jas aan de kapstok aanzien voor een persoon.","definition":"<p>Een <strong>illusionaire vervalsing</strong> is een waarnemingsstoornis waarbij een <em>bestaande</em> prikkel verkeerd wordt geïnterpreteerd: een schaduw wordt een gestalte, het geruis van de verwarming klinkt als stemmen.</p><p>Het verschilt van een hallucinatie, waarbij iets wordt waargenomen zonder dat er een prikkel is. Illusies komen voor bij vermoeidheid, angst, delier en in schemerlicht, ook bij gezonde mensen.</p>","image_url":"","wiki_title":"","match":"illusionaire vervalsing|illusie|illusies","option_only":true},"dwanggedachte":{"title":"Dwanggedachte (obsessie)","short":"Een dwanggedachte (obsessie) is een steeds terugkerende, opdringerige gedachte die als onzinnig of ongewenst wordt ervaren en angst oproept.","definition":"<p>Een <strong>dwanggedachte</strong> of obsessie is een gedachte, impuls of beeld die zich steeds opdringt, die de persoon als <em>eigen</em> maar ongewenst of overdreven herkent, en die angst of onrust geeft (bijv. angst voor besmetting of de gedachte iemand iets aan te doen).</p><p>Vaak volgen dwanghandelingen (compulsies) om de angst te verminderen, zoals wassen of controleren. Het verschil met een waan is dat de persoon het irrationele van de gedachte inziet. Kenmerkend voor de obsessieve-compulsieve stoornis (OCS).</p>","image_url":"","wiki_title":"","match":"dwanggedachte|dwanggedachten|obsessie|obsessies","option_only":true},"depressieve stoornis":{"title":"Depressieve stoornis","short":"Een depressieve stoornis kenmerkt zich door minstens twee weken een sombere stemming en/of verlies van interesse en plezier, met o.a. slaap-, eetlust- en concentratieproblemen.","definition":"<p>Voor een <strong>depressieve stoornis</strong> (DSM-5) moeten gedurende minstens twee weken vijf of meer symptomen aanwezig zijn, waaronder ten minste één kernsymptoom: <em>depressieve stemming</em> of <em>verlies van interesse of plezier</em> (anhedonie).</p><p>Andere symptomen: veranderde eetlust of gewicht, slapeloosheid of juist veel slapen, psychomotorische remming of agitatie, vermoeidheid, schuldgevoelens of waardeloosheid, concentratieproblemen en gedachten aan de dood. Behandeling met psychotherapie en/of antidepressiva.</p>","image_url":"","wiki_title":"Major depressive disorder","match":"depressieve stoornis|depressie|depressieve episode|majeure depressie","option_only":true},"insuline":{"title":"Insuline","short":"Insuline is het hormoon uit de bètacellen van de pancreas dat de bloedglucose verlaagt en opbouwprocessen stimuleert.","definition":"<p><strong>Insuline</strong> wordt afgegeven als de glucose stijgt. Het bevordert de opname van glucose in spier en vet (via GLUT4), de opslag als glycogeen en vet, en de eiwitsynthese, en remt gluconeogenese, glycogenolyse en lipolyse. Het wordt gemaakt als proinsuline; de afsplitsing van C-peptide maakt het actief. Als geneesmiddel is het onmisbaar bij diabetes type 1.</p>","image_url":"","wiki_title":"Insulin","match":"insuline|insulin","option_only":true},"adrenaline":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"adrenaline|epinefrine|epinephrine","option_only":true},"dopamine":{"title":"Dopamine","short":"Dopamine is een catecholamine-neurotransmitter, belangrijk voor motoriek, beloning en de remming van prolactine.","definition":"<p><strong>Dopamine</strong> wordt gemaakt uit tyrosine via L-DOPA. Belangrijke dopaminerge banen zijn de nigrostriatale baan (motoriek; verlies bij Parkinson), de mesolimbische en mesocorticale banen (beloning, motivatie, psychose) en de tubero-infundibulaire baan (remming van prolactine). Antipsychotica blokkeren D2-receptoren.</p>","image_url":"","wiki_title":"Dopamine","match":"dopamine","option_only":true},"histamine":{"title":"Histamine","short":"Histamine is een mediator uit mestcellen en basofielen die vaatverwijding, lekkage, jeuk en bronchoconstrictie veroorzaakt.","definition":"<p><strong>Histamine</strong> ontstaat uit histidine en ligt opgeslagen in de granula van mestcellen en basofielen. Via H1-receptoren veroorzaakt het vaatverwijding, verhoogde vaatpermeabiliteit, jeuk en bronchoconstrictie; via H2-receptoren stimuleert het de maagzuursecretie. In het brein werkt het als neurotransmitter voor waakzaamheid.</p>","image_url":"","wiki_title":"Histamine","match":"histamine","option_only":true},"glutamaat":{"title":"Glutamaat (glutaminezuur)","short":"Glutamaat is de belangrijkste prikkelende neurotransmitter in het centrale zenuwstelsel en een centraal aminozuur in de stofwisseling.","definition":"<p><strong>Glutamaat</strong> werkt op ionotrope receptoren (AMPA, NMDA, kainaat) en metabotrope receptoren. NMDA-receptoren spelen een sleutelrol bij leren en geheugen (langetermijnpotentiëring). Overmatige activatie leidt tot instroom van calcium en celdood (excitotoxiciteit), bijvoorbeeld bij ischemie. In de stofwisseling is glutamaat een knooppunt van transaminering en stikstofafvoer.</p>","image_url":"","wiki_title":"Glutamic acid","match":"glutamaat|glutaminezuur|glutamate","option_only":true},"corpus callosum":{"title":"Corpus callosum (hersenbalk)","short":"Het corpus callosum is de grote bundel witte stof die de twee hersenhelften verbindt.","definition":"<p>Het <strong>corpus callosum</strong> bevat honderden miljoenen axonen die overeenkomstige gebieden van beide hemisferen verbinden. Het bestaat uit rostrum, genu, truncus en splenium. Bij een doorsnijding of agenesie ontstaan disconnectiesyndromen; patiënten kunnen bijvoorbeeld een voorwerp in de linkerhand niet benoemen.</p>","image_url":"","wiki_title":"Corpus callosum","match":"corpus callosum|hersenbalk","option_only":true},"commisura posterior":{"title":"Commissura posterior","short":"De commissura posterior is een kleine vezelbundel boven de aquaductus die betrokken is bij de pupilreflex.","definition":"<p>De <strong>commissura posterior</strong> ligt op de overgang van diencephalon naar mesencephalon, net boven de ingang van de aquaductus cerebri. Er kruisen vezels van de pretectale kernen, die zorgen voor de consensuele pupilreactie (beide pupillen vernauwen bij licht in één oog).</p>","image_url":"","wiki_title":"Posterior commissure","match":"commisura posterior|commissura posterior","option_only":true},"commisura hippocampi":{"title":"Commissura fornicis (hippocampi)","short":"De commissura hippocampi verbindt de fornices van beide kanten en daarmee de linker en rechter hippocampus.","definition":"<p>De <strong>commissura hippocampi</strong> (commissura fornicis) ligt onder het splenium van het corpus callosum, tussen de twee crura van de fornix. Via deze vezels wisselen beide hippocampi informatie uit.</p>","image_url":"","wiki_title":"Commissure of fornix","match":"commisura hippocampi|commissura hippocampi|commissura fornicis","option_only":true},"hippocampus":{"title":"Hippocampus","short":"De hippocampus ligt in de mediale temporaalkwab en is essentieel voor het vastleggen van nieuwe herinneringen.","definition":"<p>De <strong>hippocampus</strong> is onderdeel van het limbisch systeem en ligt in de bodem van de onderhoorn van de laterale ventrikel. Hij is nodig om nieuwe episodische en ruimtelijke herinneringen op te slaan (consolidatie). De belangrijkste uitgang is de fornix. Hij is gevoelig voor hypoxie en wordt vroeg aangetast bij de ziekte van Alzheimer.</p>","image_url":"","wiki_title":"Hippocampus","match":"hippocampus","option_only":true},"nucleus caudatus":{"title":"Nucleus caudatus","short":"De nucleus caudatus is een C-vormige kern van de basale ganglia langs de laterale ventrikel; samen met het putamen vormt hij het striatum.","definition":"<p>De <strong>nucleus caudatus</strong> heeft een kop (caput) in de wand van de voorhoorn van de laterale ventrikel, een lichaam en een staart die meebuigt in de temporaalkwab. Hij ontvangt vooral input uit de prefrontale en associatiecortex en speelt een rol bij cognitieve en motivationele lussen. Bij de ziekte van Huntington atrofieert de kop van de caudatus.</p>","image_url":"","wiki_title":"Caudate nucleus","match":"nucleus caudatus|caudatus","option_only":true},"tremor":{"title":"Tremor","short":"Tremor is een onwillekeurige, ritmische, oscillerende beweging van een lichaamsdeel.","definition":"<p><strong>Tremoren</strong> worden ingedeeld naar wanneer ze optreden. Een <em>rusttremor</em> (bijv. bij de ziekte van Parkinson) is aanwezig als het lichaamsdeel ontspannen is. Een <em>houdingstremor</em> (bijv. essentiële tremor, fysiologisch versterkt bij angst, cafeïne of hyperthyreoïdie) treedt op bij het vasthouden van een houding. Een <em>intentietremor</em> neemt toe bij het naderen van een doel en wijst op cerebellaire pathologie.</p>","image_url":"","wiki_title":"Tremor","match":"tremor|beven","option_only":true},"ziekte van parkinson":{"title":"Ziekte van Parkinson","short":"De ziekte van Parkinson is een neurodegeneratieve ziekte door verlies van dopaminerge neuronen in de substantia nigra, met rusttremor, bradykinesie en rigiditeit.","definition":"<p>Bij de <strong>ziekte van Parkinson</strong> gaan dopaminerge neuronen in de substantia nigra pars compacta verloren, met Lewy-lichaampjes (alfa-synucleïne). Kernsymptomen zijn bradykinesie, rigiditeit, rusttremor en later houdingsinstabiliteit; vaak ook niet-motorische klachten zoals reukverlies, obstipatie, depressie en slaapstoornissen. Behandeling met levodopa en dopamine-agonisten.</p>","image_url":"","wiki_title":"Parkinson's disease","match":"ziekte van parkinson|parkinson|morbus parkinson","option_only":true},"vasculaire dementie":{"title":"Vasculaire dementie","short":"Vasculaire dementie is dementie door schade aan het brein door herseninfarcten, bloedingen of ziekte van de kleine vaten.","definition":"<p>Bij <strong>vasculaire dementie</strong> ontstaan cognitieve stoornissen door cerebrovasculaire schade. Het beloop kan trapsgewijs zijn (na elk infarct een verslechtering) of geleidelijk bij uitgebreide witte-stofafwijkingen. Typisch zijn een vertraagd denken en problemen met aandacht en uitvoerende functies, vaak met focale neurologische verschijnselen. Risicofactoren zijn die van hart- en vaatziekten.</p>","image_url":"","wiki_title":"Vascular dementia","match":"vasculaire dementie","option_only":true},"mci":{"title":"Mild cognitive impairment (MCI)","short":"MCI is een lichte achteruitgang van het geheugen of andere cognitieve functies die groter is dan normaal voor de leeftijd, zonder dat het dagelijks functioneren wezenlijk beperkt is.","definition":"<p>Bij <strong>mild cognitive impairment</strong> zijn cognitieve stoornissen aantoonbaar bij testen, maar kan iemand zich in het dagelijks leven nog grotendeels redden; dat onderscheidt MCI van dementie. Een deel van de mensen met MCI (vooral met geheugenstoornissen) ontwikkelt later de ziekte van Alzheimer; een ander deel blijft stabiel of verbetert.</p>","image_url":"","wiki_title":"Mild cognitive impairment","match":"mci|mild cognitive impairment|lichte cognitieve stoornis","option_only":true},"psychose":{"title":"Psychose","short":"Een psychose is een toestand waarin het contact met de werkelijkheid verstoord is, met wanen en/of hallucinaties.","definition":"<p>Bij een <strong>psychose</strong> komen wanen, hallucinaties en/of ernstig verward denken en gedrag voor. Psychosen komen voor bij schizofrenie, bipolaire stoornis, ernstige depressie, delier, middelengebruik en lichamelijke ziekten. De positieve symptomen hangen samen met een overmaat aan dopamine in de mesolimbische baan; behandeling met antipsychotica.</p>","image_url":"","wiki_title":"Psychosis","match":"psychose|psychotische stoornis","option_only":true},"kortdurende psychotische stoornis":{"title":"Kortdurende psychotische stoornis","short":"Bij een kortdurende psychotische stoornis duren de psychotische symptomen minstens een dag maar korter dan een maand, met volledig herstel.","definition":"<p>Een <strong>kortdurende psychotische stoornis</strong> (DSM-5) begint plotseling, vaak na een duidelijke stressor of rond de bevalling. Er zijn wanen, hallucinaties, gedesorganiseerde spraak of gedrag. De symptomen duren minimaal één dag en maximaal één maand, waarna het functioneren weer op het oude niveau komt.</p>","image_url":"","wiki_title":"Brief psychotic disorder","match":"kortdurende psychotische stoornis","option_only":true},"waanstoornis":{"title":"Waanstoornis","short":"Een waanstoornis kenmerkt zich door één of meer wanen die minstens een maand bestaan, zonder andere duidelijke psychotische verschijnselen.","definition":"<p>Bij een <strong>waanstoornis</strong> heeft iemand een of meer vaak niet-bizarre wanen (bijv. achtervolgings-, jaloersheids- of lichamelijke waan), terwijl het functioneren buiten het waanthema relatief goed blijft. Hallucinaties zijn afwezig of passen bij de waan, en er is geen sprake van schizofrenie.</p>","image_url":"","wiki_title":"Delusional disorder","match":"waanstoornis","option_only":true},"psychotische stoornis door een middel":{"title":"Psychotische stoornis door een middel","short":"Een psychotische stoornis door een middel wordt uitgelokt door gebruik van of onttrekking aan drugs, alcohol of medicatie.","definition":"<p>Bij een <strong>middelengeïnduceerde psychotische stoornis</strong> ontstaan wanen of hallucinaties tijdens of kort na intoxicatie of onttrekking, bijvoorbeeld door cannabis, cocaïne, amfetamine of alcohol, of door geneesmiddelen zoals corticosteroïden of dopaminerge middelen. De klachten verdwijnen meestal na stoppen; houden ze lang aan, dan moet aan een primaire psychotische stoornis worden gedacht.</p>","image_url":"","wiki_title":"Substance-induced psychosis","match":"psychotische stoornis door een middel|middelengeïnduceerde psychotische stoornis","option_only":true},"visuele hallucinatie":{"title":"Visuele hallucinatie","short":"Een visuele hallucinatie is iets zien wat er niet is, zonder dat er een prikkel aanwezig is.","definition":"<p>Een <strong>hallucinatie</strong> is een waarneming zonder prikkel, met het karakter van een echte waarneming. <em>Visuele</em> hallucinaties passen vaker bij een organische oorzaak, zoals een delier, Lewy body-dementie, de ziekte van Parkinson, intoxicaties of onttrekking, dan bij een primaire psychiatrische stoornis. Ze verschillen van een illusie, waarbij een bestaande prikkel verkeerd wordt waargenomen.</p>","image_url":"","wiki_title":"Hallucination","match":"visuele hallucinatie|visuele hallucinaties","option_only":true},"disperceptie":{"title":"Disperceptie","short":"Disperceptie is een overkoepelende term voor stoornissen in de waarneming, zoals illusies en hallucinaties.","definition":"<p>Onder <strong>disperceptie</strong> valt elke vervalsing van de waarneming: illusies (een bestaande prikkel wordt verkeerd waargenomen), hallucinaties (waarneming zonder prikkel) en pseudohallucinaties (waarbij de persoon beseft dat het niet echt is). Ze kunnen alle zintuigen betreffen.</p>","image_url":"","wiki_title":"Perceptual disturbance","match":"disperceptie|dispercepties|waarnemingsstoornis","option_only":true},"dranggedachte":{"title":"Dranggedachte","short":"Een dranggedachte is een sterk opdringerige gedachte of impuls die tot een handeling aanzet.","definition":"<p>Een <strong>dranggedachte</strong> is een gedachte of impuls die zich opdringt en aanzet tot handelen, zoals een drang om iets te doen of te controleren. In de psychopathologie wordt het vaak in één adem genoemd met dwanggedachten (obsessies), die als ongewenst en angstwekkend worden ervaren en waarvan de persoon het onzinnige inziet.</p>","image_url":"","wiki_title":"Compulsive behavior","match":"dranggedachte|dranggedachten","option_only":true},"angststoornis":{"title":"Angststoornis","short":"Een angststoornis kenmerkt zich door overmatige, aanhoudende angst of bezorgdheid die het functioneren beperkt.","definition":"<p>Tot de <strong>angststoornissen</strong> behoren o.a. de paniekstoornis, agorafobie, sociale angststoornis, specifieke fobie en gegeneraliseerde angststoornis. Er zijn psychische (angst, piekeren) en lichamelijke klachten (hartkloppingen, benauwdheid, zweten) en vaak vermijdingsgedrag. Behandeling met cognitieve gedragstherapie (exposure) en/of SSRI's.</p>","image_url":"","wiki_title":"Anxiety disorder","match":"angststoornis|angststoornissen","option_only":true},"aanpassingsstoornis":{"title":"Aanpassingsstoornis","short":"Een aanpassingsstoornis is een overmatige emotionele of gedragsmatige reactie op een duidelijke stressor, binnen drie maanden na die stressor.","definition":"<p>Bij een <strong>aanpassingsstoornis</strong> ontstaan klachten zoals somberheid, angst of gedragsproblemen als reactie op een identificeerbare gebeurtenis (bijv. ziekte, scheiding, ontslag). De klachten zijn sterker dan te verwachten of beperken het functioneren, maar voldoen niet aan de criteria van een andere stoornis, en verdwijnen meestal binnen zes maanden nadat de stressor is weggevallen.</p>","image_url":"","wiki_title":"Adjustment disorder","match":"aanpassingsstoornis","option_only":true},"vermijdende persoonlijkheidsstoornis":{"title":"Vermijdende persoonlijkheidsstoornis","short":"De vermijdende persoonlijkheidsstoornis kenmerkt zich door sociale geremdheid, gevoelens van tekortschieten en overgevoeligheid voor afwijzing.","definition":"<p>Mensen met een <strong>vermijdende persoonlijkheidsstoornis</strong> (cluster C) willen graag contact, maar vermijden sociale situaties uit angst voor kritiek, afwijzing of schaamte. Ze zien zichzelf als sociaal onhandig of minderwaardig. Er is overlap met de sociale angststoornis.</p>","image_url":"","wiki_title":"Avoidant personality disorder","match":"vermijdende persoonlijkheidsstoornis|ontwijkende persoonlijkheidsstoornis","option_only":true},"autismespectrumstoornis":{"title":"Autismespectrumstoornis","short":"Autismespectrumstoornis is een neurologische ontwikkelingsstoornis met beperkingen in sociale communicatie en beperkte, repetitieve gedragspatronen en interesses.","definition":"<p>Bij een <strong>autismespectrumstoornis</strong> zijn er vanaf de vroege ontwikkeling problemen met sociaal-emotionele wederkerigheid, non-verbale communicatie en het aangaan van relaties, gecombineerd met stereotiep gedrag, star vasthouden aan routines, beperkte interesses en afwijkende reacties op zintuiglijke prikkels. Het verloop en de ernst variëren sterk; er is een grote erfelijke component.</p>","image_url":"","wiki_title":"Autism spectrum","match":"autismespectrumstoornis|autisme|ass","option_only":true},"adhd":{"title":"ADHD","short":"ADHD is een ontwikkelingsstoornis met aandachtsproblemen en/of hyperactiviteit en impulsiviteit die in meerdere situaties optreden.","definition":"<p>Bij <strong>ADHD</strong> beginnen de klachten vóór het twaalfde jaar en zijn ze aanwezig in meerdere omgevingen (thuis, school). Er is een overwegend onoplettend, een overwegend hyperactief-impulsief en een gecombineerd beeld. Er is een sterke erfelijke component. Behandeling bestaat uit psycho-educatie, gedragsmatige interventies en zo nodig medicatie zoals methylfenidaat.</p>","image_url":"","wiki_title":"Attention deficit hyperactivity disorder","match":"adhd|aandachtstekortstoornis","option_only":true},"slaapstoornis":{"title":"Slaapstoornis","short":"Slaapstoornissen zijn problemen met de hoeveelheid, kwaliteit of timing van de slaap, of afwijkend gedrag tijdens de slaap.","definition":"<p>Onder <strong>slaapstoornissen</strong> vallen o.a. insomnie (moeite met in- of doorslapen), hypersomnie en narcolepsie, slaapgerelateerde ademhalingsstoornissen (zoals obstructieve slaapapneu), circadiane ritmestoornissen en parasomnieën (bijv. slaapwandelen, REM-slaapgedragsstoornis). Slechte slaap gaat vaak samen met psychische en lichamelijke aandoeningen.</p>","image_url":"","wiki_title":"Sleep disorder","match":"slaapstoornis|slaapstoornissen","option_only":true},"epileptische aanval":{"title":"Epileptische aanval","short":"Een epileptische aanval is een kortdurende verandering in gedrag, bewustzijn of waarneming door een abnormale, overmatige ontlading van neuronen.","definition":"<p>Een <strong>epileptische aanval</strong> kan focaal beginnen (in één hersengebied, met of zonder bewustzijnsdaling) of gegeneraliseerd zijn (bijv. tonisch-klonisch of absence). Een aanval kan uitgelokt worden (bijv. door hypoglykemie, alcoholonthouding of koorts bij jonge kinderen) of passen bij epilepsie. Een aanval die langer dan 5 minuten duurt wordt behandeld als status epilepticus.</p>","image_url":"","wiki_title":"Epileptic seizure","match":"epileptische aanval|insult|epileptisch insult","option_only":true},"vaccinatie":{"title":"Vaccinatie","short":"Vaccinatie is het toedienen van een antigeen om een beschermende, langdurige afweerreactie op te wekken zonder de ziekte door te maken.","definition":"<p>Bij <strong>actieve immunisatie</strong> wordt een verzwakt of gedood micro-organisme, een onderdeel ervan (eiwit, polysacharide, toxoïd) of een mRNA/vector die het antigeen laat aanmaken toegediend. Het lichaam maakt geheugen-B- en T-cellen. Voldoende vaccinatiegraad geeft ook groepsimmuniteit. Passieve immunisatie (antistoffen toedienen) geeft directe maar tijdelijke bescherming.</p>","image_url":"","wiki_title":"Vaccination","match":"vaccinatie|vaccin|vaccineren|immunisatie","option_only":true},"orthostatische hypotensie":{"title":"Orthostatische hypotensie","short":"Orthostatische hypotensie is een bloeddrukdaling bij het opstaan door onvoldoende compensatie van het autonome zenuwstelsel.","definition":"<p>Bij <strong>orthostatische hypotensie</strong> daalt de systolische bloeddruk met ≥20 mmHg (of de diastolische met ≥10 mmHg) binnen 3 minuten na overeind komen. Normaal zorgt de baroreflex voor vasoconstrictie en een hogere hartfrequentie. Oorzaken zijn o.a. ondervulling, medicatie (antihypertensiva, diuretica, antidepressiva) en autonome neuropathie. Klachten: duizeligheid, wazig zien en wegraking bij opstaan.</p>","image_url":"","wiki_title":"Orthostatic hypotension","match":"orthostatische hypotensie","option_only":true},"hyperkaliëmie":{"title":"Hyperkaliëmie","short":"Hyperkaliëmie is een te hoog kalium in het bloed; gevaarlijk door het risico op hartritmestoornissen.","definition":"<p><strong>Hyperkaliëmie</strong> ontstaat door verminderde uitscheiding (nierfalen, ACE-remmers, ARB's, kaliumsparende diuretica, hypoaldosteronisme), verschuiving uit de cel (acidose, insulinetekort, celafbraak) of overmatige inname. Op het ECG ziet men spitse T-toppen, verbrede QRS-complexen en uiteindelijk ventrikelfibrilleren. Acute behandeling: calciumgluconaat (membraanstabilisatie), insuline met glucose en salbutamol, en kalium verwijderen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"hyperkaliëmie|hyperkaliemie","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"metabool syndroom":{"title":"Metabool syndroom","short":"Het metabool syndroom is een combinatie van buikvetzucht, hoge bloeddruk, verhoogde glucose en een ongunstig lipidenprofiel, met een verhoogd risico op hart- en vaatziekten.","definition":"<p>Er is sprake van een <strong>metabool syndroom</strong> als minstens drie van de volgende kenmerken aanwezig zijn: een vergrote middelomtrek, verhoogde triglyceriden, verlaagd HDL-cholesterol, verhoogde bloeddruk en verhoogde nuchtere glucose. Insulineresistentie speelt een centrale rol. Het verhoogt het risico op diabetes type 2, hart- en vaatziekten en leververvetting.</p>","image_url":"","wiki_title":"Metabolic syndrome","match":"metabool syndroom|metabolisch syndroom","option_only":true},"obstipatie":{"title":"Obstipatie","short":"Obstipatie is een te harde en/of te weinig frequente ontlasting, vaak met moeizaam persen.","definition":"<p>Van <strong>obstipatie</strong> spreekt men bij minder dan drie keer per week ontlasting, harde ontlasting, persen of een gevoel van onvolledige lediging. Oorzaken zijn o.a. weinig vezels en vocht, weinig beweging, medicatie (opioïden, ijzer, anticholinergica, calciumantagonisten), hypothyreoïdie, hypercalciëmie, neurologische ziekten en obstructie door een tumor. Behandeling met leefstijladviezen en laxantia zoals macrogol.</p>","image_url":"","wiki_title":"Constipation","match":"obstipatie|verstopping|constipatie","option_only":true},"mri":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri|mri-scan|magnetic resonance imaging","option_only":true},"versterken en steunen":{"title":"Versterken en steunen","short":"Gesprekstechniek waarbij de arts de patiënt aanmoedigt en waardering uitspreekt voor wat goed gaat of wat de patiënt al doet.","definition":"<p>Bij <strong>versterken en steunen</strong> benoemt de arts de sterke kanten, inspanningen en eigen oplossingen van de patiënt (‘Knap dat u al zo lang volhoudt’). Dat vergroot het zelfvertrouwen en de motivatie. Het wordt o.a. gebruikt in motiverende gespreksvoering en bij het slechtnieuwsgesprek.</p>","image_url":"","wiki_title":"","match":"versterken en steunen","option_only":true},"erkennen en accepteren":{"title":"Erkennen en accepteren","short":"Gesprekstechniek waarbij de arts de beleving en emoties van de patiënt serieus neemt en laat merken dat die er mogen zijn.","definition":"<p>Bij <strong>erkennen</strong> laat de arts merken dat de gevoelens, zorgen of het standpunt van de patiënt begrijpelijk zijn, zonder het daarmee inhoudelijk eens te hoeven zijn. Dat voorkomt dat de patiënt zich onbegrepen voelt en zich gaat verdedigen. Het is een basisvaardigheid bij emoties, weerstand en slecht nieuws.</p>","image_url":"","wiki_title":"","match":"erkennen en accepteren|erkennen","option_only":true},"hier en nu":{"title":"Hier en nu (gesprekstechniek)","short":"Gesprekstechniek waarbij de arts benoemt wat er op dit moment in het gesprek gebeurt, om een vastgelopen gesprek weer op gang te brengen.","definition":"<p>Met een <strong>hier-en-nu</strong>-opmerking stapt de arts even uit de inhoud en bespreekt hij of zij het proces: ‘Ik merk dat we steeds over hetzelfde praten, hoe ervaart u dit gesprek?’ Dit heet ook metacommunicatie. Het helpt bij weerstand, irritatie of wanneer arts en patiënt langs elkaar heen praten.</p>","image_url":"","wiki_title":"","match":"hier en nu|hier-en-nu","option_only":true},"stiltes":{"title":"Stiltes (gesprekstechniek)","short":"Bewust stiltes laten vallen geeft de patiënt ruimte om na te denken, emoties te uiten of meer te vertellen.","definition":"<p>Een korte <strong>stilte</strong> na een vraag of na slecht nieuws laat de patiënt tijd om informatie te verwerken en zelf het woord te nemen. Veel artsen vullen stiltes te snel op. Stiltes zijn een vorm van non-verbaal aanmoedigen, naast knikken en oogcontact.</p>","image_url":"","wiki_title":"","match":"stiltes|stilte laten vallen","option_only":true},"positief her-etiketteren":{"title":"Positief her-etiketteren (reframen)","short":"Bij positief her-etiketteren geeft de arts gedrag of een uitspraak van de patiënt een andere, positievere betekenis.","definition":"<p>Bij <strong>positief her-etiketteren</strong> (reframing) wordt een negatief gelabeld gedrag in een ander licht gezet: ‘U noemt het zeuren, maar ik zie vooral iemand die goed voor zijn moeder wil zorgen.’ Het kan weerstand verminderen en nieuwe mogelijkheden openen.</p>","image_url":"","wiki_title":"","match":"positief her-etiketteren|positief heretiketteren|reframen","option_only":true},"confronteren":{"title":"Confronteren (gesprekstechniek)","short":"Bij confronteren wijst de arts de patiënt op tegenstrijdigheden in wat hij of zij zegt of doet.","definition":"<p>Bij <strong>confronteren</strong> benoemt de arts een discrepantie, bijvoorbeeld tussen woorden en gedrag (‘U zegt dat u wilt stoppen met roken, maar u bent vorige week weer begonnen’) of tussen verbale en non-verbale signalen. Goed gedoseerd en respectvol kan het tot inzicht leiden; te vroeg of te hard kan het weerstand oproepen.</p>","image_url":"","wiki_title":"","match":"confronteren|confrontatie","option_only":true},"personaliseren":{"title":"Personaliseren (gesprekstechniek)","short":"Personaliseren is een explorerende gespreksvaardigheid waarmee de arts het gesprek dichter bij de eigen ervaring van de patiënt brengt.","definition":"<p>Bij <b>personaliseren</b> wordt vaag of afstandelijk taalgebruik van de patiënt concreet en persoonlijk gemaakt, zodat duidelijk wordt wat een klacht voor deze patiënt betekent. Andere explorerende vaardigheden zijn concretiseren, doorvragen en reflecteren.</p>","image_url":"","wiki_title":"","match":"personaliseren","option_only":true},"sociale vaardigheidstraining":{"title":"Sociale vaardigheidstraining","short":"Sociale vaardigheidstraining is een gedragstherapeutische behandeling waarin mensen sociale situaties oefenen.","definition":"<p>In een <strong>sociale vaardigheidstraining</strong> worden vaardigheden zoals contact maken, voor jezelf opkomen, nee zeggen en omgaan met kritiek geoefend via instructie, rollenspel, feedback en huiswerk. Het wordt o.a. gebruikt bij sociale angst, schizofrenie en autisme.</p>","image_url":"","wiki_title":"Social skills","match":"sociale vaardigheidstraining","option_only":true},"cognitieve gedragstherapie":{"title":"Cognitieve gedragstherapie","short":"Cognitieve gedragstherapie richt zich op het veranderen van niet-helpende gedachten en gedrag.","definition":"<p>In <strong>cognitieve gedragstherapie</strong> leert iemand automatische negatieve gedachten te herkennen en te toetsen, en nieuw gedrag uit te proberen (bijv. exposure bij angst, activering bij depressie). Het is een kortdurende, gestructureerde therapie met bewezen effect bij o.a. depressie, angststoornissen, OCS, slapeloosheid en eetstoornissen.</p>","image_url":"","wiki_title":"Cognitive behavioral therapy","match":"cognitieve gedragstherapie|cgt","option_only":true},"citalopram":{"title":"Citalopram","short":"Citalopram is een SSRI (selectieve serotonineheropnameremmer) die wordt gebruikt bij depressie en angststoornissen.","definition":"<p><strong>Citalopram</strong> remt de heropname van serotonine in de presynaptische zenuwcel. Het effect op de stemming begint na enkele weken. Bijwerkingen: misselijkheid, slaapproblemen, seksuele disfunctie, hyponatriëmie (vooral bij ouderen) en een dosisafhankelijke QT-verlenging. Combinatie met andere serotonerge middelen geeft risico op een serotoninesyndroom.</p>","image_url":"","wiki_title":"Citalopram","match":"citalopram|escitalopram","option_only":true},"sertraline":{"title":"Sertraline","short":"Sertraline is een SSRI die wordt gebruikt bij depressie, angststoornissen, OCS en PTSS.","definition":"<p><strong>Sertraline</strong> remt selectief de heropname van serotonine. Het heeft relatief weinig interacties en wordt ook in de zwangerschap en bij hartpatiënten veel gebruikt. Bijwerkingen zijn vooral maag-darmklachten, slapeloosheid, seksuele disfunctie en in het begin soms meer onrust.</p>","image_url":"","wiki_title":"Sertraline","match":"sertraline","option_only":true},"antipsychotica":{"title":"Antipsychotica","short":"Antipsychotica blokkeren dopamine-D2-receptoren en worden gebruikt bij psychosen, manie en ernstige onrust.","definition":"<p>Klassieke (eerste generatie) <strong>antipsychotica</strong> zoals haloperidol geven vaak extrapiramidale bijwerkingen. Atypische (tweede generatie) middelen zoals olanzapine, risperidon, quetiapine en clozapine blokkeren ook serotonine-5-HT2A-receptoren en geven minder extrapiramidale, maar vaker metabole bijwerkingen (gewichtstoename, diabetes). Blokkade in de tubero-infundibulaire baan geeft hyperprolactinemie.</p>","image_url":"","wiki_title":"Antipsychotic","match":"antipsychotica|antipsychoticum|neuroleptica","option_only":true},"olanzapine":{"title":"Olanzapine","short":"Olanzapine is een atypisch antipsychoticum met een sterk sederend effect en een groot risico op gewichtstoename.","definition":"<p><strong>Olanzapine</strong> blokkeert dopamine-D2- en serotonine-5-HT2A-receptoren, en daarnaast histamine-H1- en muscarinereceptoren. Het wordt gebruikt bij schizofrenie en bipolaire stoornis. Bekende bijwerkingen zijn sufheid, sterke gewichtstoename, diabetes en dyslipidemie; extrapiramidale bijwerkingen zijn minder frequent dan bij haloperidol.</p>","image_url":"","wiki_title":"Olanzapine","match":"olanzapine","option_only":true},"anticonvulsiva":{"title":"Anti-epileptica","short":"Anti-epileptica (anticonvulsiva) verminderen de prikkelbaarheid van neuronen en worden gebruikt om epileptische aanvallen te voorkomen.","definition":"<p><strong>Anti-epileptica</strong> werken o.a. door blokkade van natriumkanalen (fenytoïne, carbamazepine, lamotrigine), versterking van GABA (benzodiazepinen, valproaat), blokkade van calciumkanalen (ethosuximide) of via SV2A (levetiracetam). Sommige worden ook gebruikt bij neuropathische pijn of als stemmingsstabilisator. Veel middelen zijn enzyminducerend of teratogeen (vooral valproaat).</p>","image_url":"","wiki_title":"Anticonvulsant","match":"anticonvulsiva|anti-epileptica|anticonvulsivum","option_only":true},"lamotrigine":{"title":"Lamotrigine","short":"Lamotrigine is een anti-epilepticum dat natriumkanalen blokkeert; ook gebruikt om depressieve episoden bij bipolaire stoornis te voorkomen.","definition":"<p><strong>Lamotrigine</strong> stabiliseert neuronale membranen door blokkade van spanningsafhankelijke natriumkanalen en vermindert de afgifte van glutamaat. Het moet langzaam worden opgehoogd vanwege het risico op ernstige huidreacties (Stevens-Johnson-syndroom). Valproaat verhoogt de spiegel; oestrogenen verlagen hem. Het is relatief veilig in de zwangerschap.</p>","image_url":"","wiki_title":"Lamotrigine","match":"lamotrigine","option_only":true},"topiramaat":{"title":"Topiramaat","short":"Topiramaat is een anti-epilepticum dat ook wordt gebruikt als profylaxe bij migraine.","definition":"<p><strong>Topiramaat</strong> heeft meerdere werkingsmechanismen: blokkade van natriumkanalen, versterking van GABA, remming van glutamaatreceptoren en zwakke remming van koolzuuranhydrase. Bijwerkingen zijn woordvindproblemen en cognitieve vertraging, tintelingen, gewichtsverlies, nierstenen en (zeldzaam) acuut glaucoom.</p>","image_url":"","wiki_title":"Topiramate","match":"topiramaat|topiramate","option_only":true},"naltrexon":{"title":"Naltrexon","short":"Naltrexon is een opioïdreceptorantagonist die wordt gebruikt om terugval bij alcoholverslaving te verminderen.","definition":"<p><strong>Naltrexon</strong> blokkeert µ-opioïdreceptoren en vermindert zo het belonende effect van alcohol en opioïden. Het wordt gebruikt bij alcoholafhankelijkheid (naast psychosociale behandeling) en soms bij opioïdafhankelijkheid na detoxificatie. Bij nog lopend opioïdgebruik lokt het acute onttrekkingsverschijnselen uit.</p>","image_url":"","wiki_title":"Naltrexone","match":"naltrexon|naltrexone","option_only":true},"oxazepam":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"oxazepam|benzodiazepine|benzodiazepinen","option_only":true},"morfine":{"title":"Morfine","short":"Morfine is een sterk werkend opioïd dat µ-opioïdreceptoren activeert; gebruikt bij ernstige pijn en kortademigheid in de palliatieve fase.","definition":"<p><strong>Morfine</strong> werkt pijnstillend via µ-receptoren in het centrale zenuwstelsel. Bijwerkingen zijn obstipatie (altijd een laxans erbij), misselijkheid, sufheid, ademhalingsdepressie, miosis en jeuk; bij langdurig gebruik ontstaan tolerantie en afhankelijkheid. De actieve metabolieten worden via de nier uitgescheiden en hopen op bij nierfalen. Antidotum: naloxon.</p>","image_url":"","wiki_title":"Morphine","match":"morfine|morphine","option_only":true},"cocaïne":{"title":"Cocaïne","short":"Cocaïne is een stimulerende drug die de heropname van dopamine, noradrenaline en serotonine remt en ook lokaal verdovend werkt.","definition":"<p><strong>Cocaïne</strong> geeft euforie, energie en een sterk verslavend effect. Door sympathische activatie ontstaan tachycardie, hypertensie, vasoconstrictie en hyperthermie. Complicaties zijn myocardinfarct (ook bij jonge mensen), aritmieën, herseninfarct en -bloeding, en bij snuiven een perforatie van het neustussenschot. Lokaal werkt het als natriumkanaalblokker (anestheticum).</p>","image_url":"","wiki_title":"Cocaine","match":"cocaïne|cocaine","option_only":true},"beta-blokker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"beta-blokker|bètablokker|betablokker|bètablokkers|beta-blokkers","option_only":true},"antihypertensiva":{"title":"Antihypertensiva","short":"Antihypertensiva zijn geneesmiddelen die de bloeddruk verlagen.","definition":"<p>Veelgebruikte <strong>antihypertensiva</strong> zijn thiazidediuretica, ACE-remmers en angiotensinereceptorblokkers, calciumantagonisten en bètablokkers. Daarnaast bestaan o.a. aldosteronantagonisten, alfablokkers en centraal werkende middelen. De keuze hangt af van comorbiditeit, leeftijd, afkomst en bijwerkingen; vaak is een combinatie nodig.</p>","image_url":"","wiki_title":"Antihypertensive drug","match":"antihypertensiva|antihypertensivum|bloeddrukverlagers","option_only":true},"anorexia nervosa":{"title":"Anorexia nervosa","short":"Anorexia nervosa is een eetstoornis met een te laag lichaamsgewicht door het beperken van voeding, angst om aan te komen en een verstoord lichaamsbeeld.","definition":"<p>Bij <strong>anorexia nervosa</strong> houdt iemand het gewicht bewust laag, met een intense angst om dik te worden. Lichamelijke gevolgen zijn o.a. amenorroe, bradycardie, hypotensie, hypothermie, lanugobeharing, osteoporose en elektrolytstoornissen (vooral bij braken of laxeren). Het heeft de hoogste sterfte van de psychiatrische stoornissen. Bij het hervatten van voeding dreigt het refeedingsyndroom.</p>","image_url":"","wiki_title":"Anorexia nervosa","match":"anorexia nervosa","option_only":true},"corticosteroïden":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"corticosteroïden|corticosteroiden|glucocorticoïden|corticosteroïd","option_only":true},"hyponatriëmie":{"title":"Hyponatriëmie","short":"Hyponatriëmie is een te laag natrium in het bloed, meestal door een relatief overschot aan water.","definition":"<p><strong>Hyponatriëmie</strong> (&lt;135 mmol/L) wordt ingedeeld naar de volumestatus: ondervuld (bijv. braken, diuretica), normovolemisch (bijv. SIADH, hypothyreoïdie, bijnierinsufficiëntie) of overvuld (hartfalen, cirrose, nierfalen). Ernstige of snel ontstane hyponatriëmie geeft hersenoedeem met verwardheid, insulten en coma. Te snelle correctie kan osmotische demyelinisatie veroorzaken.</p>","image_url":"","wiki_title":"Hyponatremia","match":"hyponatriëmie|hyponatriemie","option_only":true},"perifeer oedeem":{"title":"Perifeer oedeem","short":"Perifeer oedeem is vochtophoping in de benen en voeten, vaak putjes achterlatend bij indrukken.","definition":"<p><strong>Perifeer oedeem</strong> ontstaat door een verhoogde veneuze druk (rechtszijdig hartfalen, veneuze insufficiëntie, trombose), een laag albumine (nefrotisch syndroom, cirrose, ondervoeding), medicatie (calciumantagonisten, NSAID's) of lymfoedeem. Eenzijdig oedeem past vaker bij een lokale oorzaak, zoals trombose of cellulitis.</p>","image_url":"","wiki_title":"Edema","match":"perifeer oedeem|enkeloedeem","option_only":true},"cannabis":{"title":"Cannabis","short":"Cannabis bevat THC, dat via cannabinoïde receptoren ontspanning en veranderde waarneming geeft; zwaar gebruik vergroot het risico op psychose.","definition":"<p><strong>Cannabis</strong> werkt via CB1-receptoren in het brein. Acuut geeft het euforie, ontspanning, verhoogde eetlust, tachycardie, rode ogen en verminderde concentratie en reactiesnelheid. Langdurig en vooral jong, zwaar gebruik van THC-rijke cannabis verhoogt het risico op psychose en schizofrenie. Het cannabinoïde-hyperemesissyndroom geeft heftig braken dat verbetert met warm douchen.</p>","image_url":"","wiki_title":"Cannabis (drug)","match":"cannabis|hasj|wiet|thc","option_only":true},"ticstoornis":{"title":"Ticstoornis","short":"Een ticstoornis kenmerkt zich door plotselinge, snelle, herhaalde bewegingen of klanken die moeilijk te onderdrukken zijn.","definition":"<p><strong>Tics</strong> kunnen motorisch (knipperen, grimassen) of vocaal (keelschrapen, woorden) zijn en worden vaak voorafgegaan door een drang. Ze beginnen meestal in de kindertijd en nemen vaak af na de puberteit. Bij het <em>syndroom van Gilles de la Tourette</em> zijn er meerdere motorische en minstens één vocale tic, langer dan een jaar; vaak met ADHD of OCS.</p>","image_url":"","wiki_title":"Tic disorder","match":"ticstoornis|tics|syndroom van gilles de la tourette|tourette","option_only":true},"stereotypie":{"title":"Stereotypie","short":"Een stereotypie is een herhaalde, doelloze beweging of handeling, zoals wiegen of handfladderen.","definition":"<p><strong>Stereotypieën</strong> zijn ritmisch en patroonmatig en worden niet als ongewenst ervaren, anders dan tics. Ze komen voor bij autismespectrumstoornis, verstandelijke beperking, ernstige sensorische deprivatie, katatonie en als bijwerking (bijv. van stimulantia).</p>","image_url":"","wiki_title":"Stereotypy","match":"stereotypie|stereotypieën|stereotiep gedrag","option_only":true},"norm-overschrijdende gedragsstoornis":{"title":"Normoverschrijdende-gedragsstoornis","short":"De normoverschrijdende-gedragsstoornis is een patroon van gedrag bij kinderen en jongeren waarbij rechten van anderen en sociale regels worden geschonden.","definition":"<p>Bij een <strong>normoverschrijdende-gedragsstoornis</strong> zijn er o.a. agressie tegen mensen of dieren, vernieling, liegen of stelen en ernstige overtredingen van regels (spijbelen, weglopen). Risicofactoren zijn erfelijke aanleg, ADHD, onveilige opvoeding en armoede. Het kan overgaan in een antisociale persoonlijkheidsstoornis op volwassen leeftijd.</p>","image_url":"","wiki_title":"Conduct disorder","match":"norm-overschrijdende gedragsstoornis|normoverschrijdende gedragsstoornis|gedragsstoornis|conduct disorder","option_only":true},"depressie met psychotische kenmerken":{"title":"Psychotische depressie","short":"Bij een depressie met psychotische kenmerken gaat een ernstige depressie samen met wanen en/of hallucinaties, vaak met een somber thema.","definition":"<p>De wanen bij een <strong>psychotische depressie</strong> zijn meestal stemmingscongruent: schuld, armoede, nihilisme of ernstige ziekte. Het suïciderisico is hoog. Behandeling bestaat uit een combinatie van een antidepressivum en een antipsychoticum, of elektroconvulsietherapie, die bij deze vorm zeer effectief is.</p>","image_url":"","wiki_title":"Psychotic depression","match":"depressie met psychotische kenmerken|psychotische depressie","option_only":true},"persoonlijkheidsverandering door somatische aandoening":{"title":"Persoonlijkheidsverandering door een somatische aandoening","short":"Een persoonlijkheidsverandering door een somatische aandoening is een blijvende verandering in karakter door hersenschade of -ziekte.","definition":"<p>Bij deze stoornis verandert de persoonlijkheid duidelijk ten opzichte van vroeger, bijvoorbeeld met ontremming, apathie, prikkelbaarheid of achterdocht, als direct gevolg van een lichamelijke aandoening. Voorbeelden zijn schade aan de frontaalkwab door trauma, tumor of frontotemporale dementie, en temporaalkwabepilepsie.</p>","image_url":"","wiki_title":"Personality change","match":"persoonlijkheidsverandering door somatische aandoening|organische persoonlijkheidsverandering","option_only":true},"alcoholmisbruik":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcoholmisbruik","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"globus pallidus externa":{"title":"Globus pallidus pars externa (GPe)","short":"De GPe is onderdeel van de basale kernen en vormt een schakel in de indirecte route; hij remt de nucleus subthalamicus.","definition":"<p>De <strong>globus pallidus pars externa</strong> is het laterale deel van de globus pallidus. Hij ontvangt remmende (GABA-erge) input van het striatum en stuurt zelf remmende projecties naar de nucleus subthalamicus.</p><p>Hij is een kernschakel van de <em>indirecte route</em> van de basale kernen (cortex → striatum → GPe → nucleus subthalamicus → GPi/SNr → thalamus), die beweging per saldo afremt.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus externa","option_only":true},"globus pallidus interna":{"title":"Globus pallidus pars interna (GPi)","short":"De GPi is de belangrijkste uitgangskern van de basale kernen; hij remt (GABA-erg) de motorische thalamus.","definition":"<p>De <strong>globus pallidus pars interna</strong> is samen met de substantia nigra pars reticulata de <em>uitgangskern</em> van de basale kernen. Hij geeft tonisch remmende GABA-erge output naar de motorische kernen van de thalamus.</p><p>De directe route (striatum → GPi) remt de GPi en ontremt zo de thalamus (meer beweging); de indirecte route versterkt via de nucleus subthalamicus juist de remming. De GPi is een doelwit bij diepe hersenstimulatie (o.a. dystonie, Parkinson).</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus interna","option_only":true},"tricyclisch antidepressivum":{"title":"Tricyclische antidepressiva","short":"Tricyclische antidepressiva remmen de heropname van noradrenaline en serotonine en hebben veel anticholinerge bijwerkingen.","definition":"<p><strong>TCA's</strong> (zoals amitriptyline, nortriptyline, clomipramine) worden gebruikt bij depressie en in lage dosis bij neuropathische pijn. Bijwerkingen: droge mond, obstipatie, urineretentie, sufheid, orthostatische hypotensie en gewichtstoename. Bij overdosering zijn ze gevaarlijk door natriumkanaalblokkade (breed QRS, aritmieën) en insulten.</p>","image_url":"","wiki_title":"Tricyclic antidepressant","match":"tricyclisch antidepressivum|tricyclische antidepressiva|tca|amitriptyline|nortriptyline","option_only":true},"ecstasy (xtc)":{"title":"Ecstasy (MDMA)","short":"Ecstasy (MDMA) is een stimulerende drug die vooral serotonine (en dopamine, noradrenaline) laat vrijkomen.","definition":"<p><strong>MDMA</strong> geeft euforie, verbondenheid en energie. Risico's zijn hyperthermie, uitdroging of juist hyponatriëmie (door veel water drinken en ADH-afgifte), serotoninesyndroom, hartritmestoornissen en zelden leverfalen. Na gebruik kan een tijdelijke somberheid optreden.</p>","image_url":"","wiki_title":"MDMA","match":"ecstasy (xtc)|ecstasy|xtc|mdma","option_only":true},"melatonine":{"title":"Melatonine","short":"Melatonine is een hormoon uit de pijnappelklier dat in het donker wordt afgegeven en het slaap-waakritme helpt regelen.","definition":"<p><strong>Melatonine</strong> wordt gemaakt uit serotonine en vooral ’s avonds en ’s nachts afgegeven; licht (via de retina en nucleus suprachiasmaticus) remt de afgifte. Als middel wordt het gebruikt bij een verschoven slaapritme, jetlag en bepaalde slaapproblemen bij kinderen en ouderen; als slaapmiddel is het effect bescheiden.</p>","image_url":"","wiki_title":"Melatonin","match":"melatonine|melatonin","option_only":true},"paniekaanval":{"title":"Paniekaanval","short":"Een paniekaanval is een plotselinge golf van intense angst met lichamelijke klachten, die binnen minuten een piek bereikt.","definition":"<p>Tijdens een <strong>paniekaanval</strong> ontstaan o.a. hartkloppingen, zweten, trillen, benauwdheid, druk op de borst, duizeligheid, tintelingen en angst om dood te gaan of gek te worden. Bij een <strong>paniekstoornis</strong> zijn er herhaalde, onverwachte aanvallen met aanhoudende angst voor nieuwe aanvallen. Behandeling met cognitieve gedragstherapie en/of SSRI's.</p>","image_url":"","wiki_title":"Panic attack","match":"paniekaanval|paniekstoornis","option_only":true},"paroxetine":{"title":"Paroxetine","short":"Paroxetine is een SSRI met relatief veel anticholinerge bijwerkingen en ontwenningsverschijnselen bij stoppen.","definition":"<p><strong>Paroxetine</strong> remt de heropname van serotonine en wordt gebruikt bij depressie en angststoornissen. Het heeft een korte halfwaardetijd, waardoor abrupt stoppen vaak onttrekkingsverschijnselen geeft. Het is een sterke CYP2D6-remmer (interacties, o.a. met tamoxifen) en wordt in de zwangerschap liever vermeden.</p>","image_url":"","wiki_title":"Paroxetine","match":"paroxetine","option_only":true},"blaasretentie":{"title":"Urineretentie","short":"Bij urineretentie kan iemand de blaas niet (volledig) legen, acuut met pijnlijke volle blaas of chronisch met overloopincontinentie.","definition":"<p><strong>Urineretentie</strong> ontstaat door een obstructie (prostaatvergroting, urethrastrictuur, stolsels), medicatie (anticholinergica, opioïden), neurologische oorzaken (dwarslaesie, cauda-equinasyndroom, diabetische neuropathie) of na operaties en anesthesie. Acute retentie wordt behandeld met een katheter.</p>","image_url":"","wiki_title":"Urinary retention","match":"blaasretentie|urineretentie|retentieblaas","option_only":true},"diffuse intravasale stolling (dis)":{"title":"Diffuse intravasale stolling (DIS)","short":"Bij DIS wordt de stolling in het hele lichaam ontregeld geactiveerd, met microtrombi én bloedingen door verbruik van stollingsfactoren en plaatjes.","definition":"<p><strong>DIS</strong> ontstaat bij o.a. sepsis, trauma, obstetrische complicaties (placentaloslating, vruchtwaterembolie), acute promyelocytenleukemie en uitgebreide tumoren. Kenmerken: daling van plaatjes en fibrinogeen, verlengde PT/APTT en sterk verhoogde D-dimeer, met orgaanschade en bloedingen. Behandeling van de oorzaak staat centraal.</p>","image_url":"","wiki_title":"Disseminated intravascular coagulation","match":"diffuse intravasale stolling (dis)|diffuse intravasale stolling|dis|dic","option_only":true},"arginine":{"title":"Arginine","short":"Arginine is een aminozuur waaruit in de ureumcyclus ureum ontstaat en waaruit NO-synthase stikstofmonoxide maakt.","definition":"<p>In de lever splitst arginase <strong>arginine</strong> in ureum en ornithine. In endotheel en andere cellen is arginine het substraat voor NO-synthase. Arginine stimuleert ook de afgifte van groeihormoon en insuline, en activeert de vorming van N-acetylglutamaat.</p>","image_url":"","wiki_title":"Arginine","match":"arginine|arganine","option_only":true},"longontsteking door sars-cov-2":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"longontsteking door sars-cov-2","option_only":true},"amyotrofische laterale sclerose":{"title":"Amyotrofische laterale sclerose (ALS)","short":"ALS is een progressieve, dodelijke ziekte van zowel het bovenste als het onderste motorneuron.","definition":"<p>Bij <strong>ALS</strong> ontstaan asymmetrische zwakte, atrofie en fasciculaties (onderste motorneuron) samen met spasticiteit en hyperreflexie (bovenste motorneuron), vaak met slik- en spraakproblemen. Gevoel, oogbewegingen en blaasfunctie blijven meestal gespaard. Een deel heeft ook frontotemporale dementie. Riluzol vertraagt het beloop iets.</p>","image_url":"","wiki_title":"Amyotrophic lateral sclerosis","match":"amyotrofische laterale sclerose|als","option_only":true},"posttraumatische stressstoornis":{"title":"Posttraumatische stressstoornis (PTSS)","short":"PTSS ontstaat na een schokkende gebeurtenis, met herbelevingen, vermijding, negatieve stemming en verhoogde prikkelbaarheid.","definition":"<p>Bij <strong>PTSS</strong> duren de klachten langer dan een maand: herbelevingen (nachtmerries, flashbacks), vermijding van herinneringen, negatieve veranderingen in denken en stemming, en verhoogde waakzaamheid en schrikreacties. Behandeling met traumagerichte therapie (EMDR, cognitieve gedragstherapie), eventueel SSRI's.</p>","image_url":"","wiki_title":"Posttraumatic stress disorder","match":"posttraumatische stressstoornis|ptss|ptsd","option_only":true},"bipolaire stoornis":{"title":"Bipolaire stoornis","short":"Bij een bipolaire stoornis wisselen depressieve episoden af met manische (type I) of hypomane (type II) episoden.","definition":"<p>Een <strong>manie</strong> kenmerkt zich door een verhoogde of prikkelbare stemming, minder slaapbehoefte, gedachtevlucht, grootheidsideeën en risicovol gedrag, soms met psychotische kenmerken. Stemmingsstabilisatoren zoals lithium, valproaat en lamotrigine en sommige antipsychotica worden gebruikt; antidepressiva alleen kunnen een manie uitlokken.</p>","image_url":"","wiki_title":"Bipolar disorder","match":"bipolaire stoornis|manisch-depressieve stoornis","option_only":true},"borderline-persoonlijkheidsstoornis":{"title":"Borderline-persoonlijkheidsstoornis","short":"De borderline-persoonlijkheidsstoornis kenmerkt zich door instabiliteit in relaties, zelfbeeld en emoties, en impulsiviteit.","definition":"<p>Kenmerken zijn angst om verlaten te worden, intense en wisselende relaties, een instabiel zelfbeeld, impulsiviteit, terugkerende zelfbeschadiging of suïcidaliteit, stemmingswisselingen, chronische leegte, woede-uitbarstingen en kortdurende paranoïde ideeën bij stress. Behandeling met psychotherapie (bijv. DGT, MBT, schematherapie).</p>","image_url":"","wiki_title":"Borderline personality disorder","match":"borderline-persoonlijkheidsstoornis|borderline","option_only":true},"ziekte van alzheimer":{"title":"Ziekte van Alzheimer","short":"De ziekte van Alzheimer is de meest voorkomende oorzaak van dementie, met geleidelijk verlies van vooral het episodisch geheugen.","definition":"<p>Bij <strong>Alzheimer</strong> stapelen zich amyloïdplaques en neurofibrillaire tangles (tau) op, met verlies van neuronen, beginnend in de mediale temporaalkwab. Later volgen problemen met taal, oriëntatie, uitvoerende functies en gedrag. Cholinesteraseremmers en memantine geven een bescheiden symptomatisch effect.</p>","image_url":"","wiki_title":"Alzheimer's disease","match":"ziekte van alzheimer|alzheimer|alzheimerdementie","option_only":true},"gaba":{"title":"GABA","short":"GABA is de belangrijkste remmende neurotransmitter in de hersenen.","definition":"<p><strong>GABA</strong> wordt gemaakt uit glutamaat (door glutamaatdecarboxylase, met vitamine B6). Het werkt via GABA-A-receptoren (chloridekanalen; versterkt door benzodiazepinen, barbituraten, alcohol) en GABA-B-receptoren (G-eiwitgekoppeld; baclofen).</p>","image_url":"","wiki_title":"Gamma-Aminobutyric acid","match":"gaba|gamma-aminoboterzuur","option_only":true},"norepinephrine":{"title":"Noradrenaline (norepinefrine)","short":"Noradrenaline is de neurotransmitter van de postganglionaire sympathische vezels en een vaatvernauwend middel bij shock.","definition":"<p><strong>Noradrenaline</strong> werkt vooral op α1-receptoren (vasoconstrictie) en β1-receptoren. Centraal komt het uit de locus coeruleus (alertheid, stemming). Als geneesmiddel is het de vasopressor van eerste keus bij septische shock.</p>","image_url":"","wiki_title":"Norepinephrine","match":"norepinephrine|noradrenaline|norepinefrine","option_only":true},"natriumvalproaat":{"title":"Valproïnezuur","short":"Valproaat is een breed werkend anti-epilepticum en stemmingsstabilisator, maar sterk teratogeen.","definition":"<p><strong>Valproaat</strong> werkt o.a. via versterking van GABA en blokkade van natriumkanalen. Het werkt goed bij gegeneraliseerde epilepsieën en bij bipolaire stoornis. Bij gebruik in de zwangerschap is er een groot risico op aangeboren afwijkingen (neuralebuisdefecten) en ontwikkelingsproblemen; bij vrouwen in de vruchtbare leeftijd wordt het daarom zo veel mogelijk vermeden. Andere bijwerkingen: gewichtstoename, tremor, haaruitval, leverschade en hyperammoniëmie.</p>","image_url":"","wiki_title":"Valproate","match":"natriumvalproaat|valproïnezuur|valproaat|valproinezuur","option_only":true},"schizoaffectieve stoornis":{"title":"Schizoaffectieve stoornis","short":"Bij een schizoaffectieve stoornis komen psychotische symptomen van schizofrenie samen voor met episoden van depressie of manie.","definition":"<p>Voor de diagnose moeten er ook periodes van minstens twee weken met wanen of hallucinaties zonder stemmingsstoornis zijn geweest. Behandeling combineert antipsychotica met stemmingsstabilisatoren of antidepressiva.</p>","image_url":"","wiki_title":"Schizoaffective disorder","match":"schizoaffectieve stoornis","option_only":true},"oppositionele gedragsstoornis":{"title":"Oppositioneel-opstandige stoornis","short":"De oppositioneel-opstandige stoornis is een patroon van boze stemming, opstandig gedrag en wraakzucht bij kinderen.","definition":"<p>Kinderen met <strong>ODD</strong> zijn vaak prikkelbaar, maken ruzie met volwassenen, weigeren regels te volgen en geven anderen de schuld. Het kan voorafgaan aan een normoverschrijdende-gedragsstoornis. Ouder- en gedragstraining zijn de belangrijkste behandelingen.</p>","image_url":"","wiki_title":"Oppositional defiant disorder","match":"oppositionele gedragsstoornis|oppositionele-opstandige stoornis|odd","option_only":true},"specifieke leerstoornis":{"title":"Specifieke leerstoornis","short":"Een specifieke leerstoornis is een hardnekkig probleem met lezen, spellen of rekenen, ondanks normale intelligentie en goed onderwijs.","definition":"<p>Voorbeelden zijn <strong>dyslexie</strong> (lezen en spellen) en <strong>dyscalculie</strong> (rekenen). De problemen beginnen in de schooljaren en zijn niet te verklaren door verstandelijke beperking, zintuigproblemen of onvoldoende onderwijs.</p>","image_url":"","wiki_title":"Learning disability","match":"specifieke leerstoornis|leerstoornis|dyslexie|dyscalculie","option_only":true},"dementie door de ziekte van parkinson":{"title":"Parkinsondementie","short":"Parkinsondementie is dementie die ontstaat bij iemand die al langer (meer dan een jaar) de ziekte van Parkinson heeft.","definition":"<p>Bij <strong>parkinsondementie</strong> staan traagheid van denken, aandachts- en uitvoerende stoornissen en visuospatiële problemen op de voorgrond, vaak met visuele hallucinaties. Als de dementie binnen een jaar na of vóór de motorische klachten begint, spreekt men van Lewy body-dementie.</p>","image_url":"","wiki_title":"Parkinson's disease dementia","match":"dementie door de ziekte van parkinson|parkinsondementie","option_only":true},"cluster b":{"title":"Cluster B-persoonlijkheidsstoornissen","short":"Cluster B omvat de ‘dramatische, emotionele of grillige’ persoonlijkheidsstoornissen: antisociaal, borderline, histrionisch en narcistisch.","definition":"<p>Mensen met een <strong>cluster B</strong>-stoornis hebben vaak problemen met emotieregulatie, impulsiviteit en relaties. Cluster A is ‘vreemd/excentriek’ (paranoïde, schizoïde, schizotypisch), cluster C ‘angstig/vermijdend’ (vermijdend, afhankelijk, dwangmatig).</p>","image_url":"","wiki_title":"Cluster B personality disorders","match":"cluster b","option_only":true},"cluster c":{"title":"Cluster C-persoonlijkheidsstoornissen","short":"Cluster C omvat de ‘angstige en vermijdende’ persoonlijkheidsstoornissen: vermijdend, afhankelijk en dwangmatig.","definition":"<p>Bij <strong>cluster C</strong>-persoonlijkheidsstoornissen staan angst, onzekerheid en controlebehoefte centraal. Psychotherapie is de belangrijkste behandeling.</p>","image_url":"","wiki_title":"Cluster C personality disorders","match":"cluster c","option_only":true},"obsessie en compulsie":{"title":"Obsessies en compulsies (OCS)","short":"Bij een obsessieve-compulsieve stoornis zijn er dwanggedachten (obsessies) en/of dwanghandelingen (compulsies) die veel tijd kosten en lijden geven.","definition":"<p>Bij <strong>OCS</strong> roepen obsessies (bijv. over besmetting, schade, symmetrie) angst op, die met compulsies (wassen, controleren, ordenen, tellen) tijdelijk wordt verminderd. De persoon ziet meestal in dat de gedachten overdreven zijn. Behandeling met exposure en responspreventie en/of SSRI's.</p>","image_url":"","wiki_title":"Obsessive–compulsive disorder","match":"obsessie en compulsie|obsessieve-compulsieve stoornis|ocs|dwangstoornis","option_only":true},"maprotiline":{"title":"Maprotiline","short":"Maprotiline is een tetracyclisch antidepressivum dat vooral de heropname van noradrenaline remt.","definition":"<p><strong>Maprotiline</strong> lijkt in werking en bijwerkingen op de tricyclische antidepressiva (anticholinerg, sedatie). Het verlaagt de insultdrempel. Het wordt weinig meer gebruikt.</p>","image_url":"","wiki_title":"Maprotiline","match":"maprotiline","option_only":true},"de ziekte van creutzfeldt-jacob":{"title":"Ziekte van Creutzfeldt-Jakob","short":"De ziekte van Creutzfeldt-Jakob is een snel progressieve, dodelijke prionziekte met dementie en myoclonieën.","definition":"<p>De meeste gevallen zijn sporadisch; daarnaast zijn er erfelijke en verworven vormen (iatrogeen, variant-CJD via BSE). Kenmerkend zijn een snel progressieve dementie, myoclonieën, ataxie, periodieke complexen op het EEG en afwijkingen op MRI; de RT-QuIC-test in liquor kan prionen aantonen.</p>","image_url":"","wiki_title":"Creutzfeldt–Jakob disease","match":"de ziekte van creutzfeldt-jacob|ziekte van creutzfeldt-jakob|creutzfeldt-jakob","option_only":true},"non-rem-slaap-arousalstoornis":{"title":"Non-REM-slaap-arousalstoornis","short":"Bij non-REM-arousalstoornissen ontwaakt iemand gedeeltelijk uit de diepe slaap, met slaapwandelen of nachtelijke angstaanvallen.","definition":"<p>Bij <strong>slaapwandelen</strong> en <strong>pavor nocturnus</strong> (nachtmerrieachtige schrikreacties) is iemand moeilijk te wekken en herinnert hij of zij zich het voorval meestal niet. Het komt vooral bij kinderen voor in het eerste deel van de nacht. Een REM-slaapgedragsstoornis daarentegen geeft het naspelen van dromen, vaak bij ouderen en geassocieerd met Parkinson.</p>","image_url":"","wiki_title":"Non-rapid eye movement sleep arousal disorders","match":"non-rem-slaap-arousalstoornis|slaapwandelen|pavor nocturnus","option_only":true},"gevoelshallucinatie":{"title":"Tactiele hallucinatie","short":"Bij een tactiele hallucinatie voelt iemand iets op of in de huid zonder prikkel, zoals beestjes die over de huid kruipen.","definition":"<p><strong>Tactiele hallucinaties</strong> komen vooral voor bij intoxicatie of onttrekking (cocaïne, amfetamine, alcoholdelier) en bij een dermatozoënwaan.</p>","image_url":"","wiki_title":"Tactile hallucination","match":"gevoelshallucinatie|tactiele hallucinatie|formicatie","option_only":true},"paranoïde-persoonlijkheidsstoornis":{"title":"Paranoïde persoonlijkheidsstoornis","short":"Bij een paranoïde persoonlijkheidsstoornis is er een diepgeworteld wantrouwen en achterdocht naar anderen.","definition":"<p>Mensen met een <strong>paranoïde persoonlijkheidsstoornis</strong> (cluster A) verwachten dat anderen hen willen benadelen, zijn snel gekrenkt, wrokkig en terughoudend in het delen van informatie, zonder dat er sprake is van een psychose.</p>","image_url":"","wiki_title":"Paranoid personality disorder","match":"paranoïde-persoonlijkheidsstoornis|paranoïde persoonlijkheidsstoornis","option_only":true},"histrionische-persoonlijkheidsstoornis":{"title":"Histrionische persoonlijkheidsstoornis","short":"De histrionische persoonlijkheidsstoornis kenmerkt zich door overmatige emotionaliteit en aandacht zoeken.","definition":"<p>Mensen met een <strong>histrionische persoonlijkheidsstoornis</strong> (cluster B) willen in het middelpunt staan, gedragen zich theatraal of verleidelijk, hebben snel wisselende, oppervlakkige emoties en zijn beïnvloedbaar.</p>","image_url":"","wiki_title":"Histrionic personality disorder","match":"histrionische-persoonlijkheidsstoornis|histrionische persoonlijkheidsstoornis","option_only":true},"schizotypische-persoonlijkheidsstoornis":{"title":"Schizotypische persoonlijkheidsstoornis","short":"De schizotypische persoonlijkheidsstoornis kenmerkt zich door sociaal ongemak, eigenaardig denken en gedrag en ongewone waarnemingen.","definition":"<p>Mensen met een <strong>schizotypische persoonlijkheidsstoornis</strong> (cluster A) hebben magisch denken, betrekkingsideeën, achterdocht en weinig vertrouwelijke relaties, zonder volledige psychose. Er is genetische verwantschap met schizofrenie.</p>","image_url":"","wiki_title":"Schizotypal personality disorder","match":"schizotypische-persoonlijkheidsstoornis|schizotypische persoonlijkheidsstoornis","option_only":true},"dwangmatige persoonlijkheidsstoornis":{"title":"Obsessieve-compulsieve persoonlijkheidsstoornis","short":"De dwangmatige persoonlijkheidsstoornis kenmerkt zich door perfectionisme, ordelijkheid en controle, ten koste van flexibiliteit.","definition":"<p>Mensen met een <strong>dwangmatige persoonlijkheidsstoornis</strong> (cluster C) zijn rigide, overmatig toegewijd aan werk, moeilijk in het delegeren en vaak gierig. In tegenstelling tot OCS zijn er geen echte obsessies en compulsies en wordt het gedrag als bij zichzelf passend ervaren.</p>","image_url":"","wiki_title":"Obsessive–compulsive personality disorder","match":"dwangmatige persoonlijkheidsstoornis|obsessieve-compulsieve persoonlijkheidsstoornis","option_only":true},"gegeneraliseerde angststoornis":{"title":"Gegeneraliseerde angststoornis","short":"Bij een gegeneraliseerde angststoornis piekert iemand overmatig en moeilijk te stoppen over allerlei zaken, met lichamelijke spanning.","definition":"<p>Bij een <strong>gegeneraliseerde angststoornis</strong> zijn er minstens zes maanden piekeren met rusteloosheid, vermoeidheid, concentratieproblemen, prikkelbaarheid, spierspanning en slaapproblemen. Behandeling met cognitieve gedragstherapie, toegepaste ontspanning en/of SSRI's.</p>","image_url":"","wiki_title":"Generalized anxiety disorder","match":"gegeneraliseerde angststoornis|gas-stoornis|piekerstoornis","option_only":true},"boulimia nervosa":{"title":"Boulimia nervosa","short":"Bij boulimia nervosa zijn er herhaalde eetbuien met compensatiegedrag, zoals braken, laxeren of overmatig sporten.","definition":"<p>Mensen met <strong>boulimia nervosa</strong> hebben vaak een normaal gewicht. Lichamelijke gevolgen van braken zijn hypokaliëmie met metabole alkalose, tanderosie, gezwollen speekselklieren en eelt op de knokkels (teken van Russell). Behandeling met cognitieve gedragstherapie.</p>","image_url":"","wiki_title":"Bulimia nervosa","match":"boulimia nervosa|boulimie","option_only":true},"insomnia":{"title":"Insomnie","short":"Insomnie is aanhoudend moeite met inslapen, doorslapen of te vroeg wakker worden, met klachten overdag.","definition":"<p>Bij <strong>chronische insomnie</strong> (minstens drie nachten per week, drie maanden) is cognitieve gedragstherapie voor insomnie de eerste keus, met o.a. slaaprestrictie en stimuluscontrole. Slaapmiddelen zijn alleen kortdurend geschikt wegens gewenning en afhankelijkheid.</p>","image_url":"","wiki_title":"Insomnia","match":"insomnia|insomnie|slapeloosheid","option_only":true},"applied relaxation":{"title":"Toegepaste ontspanning","short":"Toegepaste ontspanning is een therapie waarin iemand leert snel te ontspannen en dat toe te passen in angstwekkende situaties.","definition":"<p><strong>Applied relaxation</strong> (Öst) wordt vooral gebruikt bij de gegeneraliseerde angststoornis en paniekklachten. Via stappen van progressieve spierontspanning leert iemand binnen enkele seconden te ontspannen bij de eerste tekenen van spanning.</p>","image_url":"","wiki_title":"","match":"applied relaxation|toegepaste ontspanning","option_only":true},"psycho-educatie":{"title":"Psycho-educatie","short":"Psycho-educatie is uitleg aan patiënt en naasten over een aandoening, het beloop en de behandeling, zodat zij er beter mee om kunnen gaan.","definition":"<p><strong>Psycho-educatie</strong> is een basisonderdeel van vrijwel elke behandeling in de psychiatrie en somatiek. Het vermindert angst en schaamte, verbetert therapietrouw en helpt vroege signalen van terugval te herkennen.</p>","image_url":"","wiki_title":"Psychoeducation","match":"psycho-educatie|psychoeducatie","option_only":true},"simulatie":{"title":"Simulatie","short":"Bij simulatie veinst iemand bewust ziekte of klachten om een uitwendig voordeel te behalen, zoals geld of het ontlopen van werk.","definition":"<p><strong>Simulatie</strong> is geen psychiatrische stoornis. Het verschil met een nagebootste stoornis is de motivatie: bij simulatie een extern voordeel, bij een nagebootste stoornis de ziekterol zelf.</p>","image_url":"","wiki_title":"Malingering","match":"simulatie|simuleren","option_only":true},"fronto-temporale dementie":{"title":"Frontotemporale dementie","short":"Frontotemporale dementie is een dementie op relatief jonge leeftijd met vooral gedragsveranderingen of taalproblemen.","definition":"<p>Bij de gedragsvariant van <strong>FTD</strong> staan ontremming, apathie, verlies van empathie, dwangmatig gedrag en veranderde eetgewoonten op de voorgrond, terwijl het geheugen lang relatief goed blijft. Er bestaan ook taalvarianten. Het is vaak erfelijk en kan samengaan met ALS.</p>","image_url":"","wiki_title":"Frontotemporal dementia","match":"fronto-temporale dementie|frontotemporale dementie|ftd","option_only":true},"heroïne":{"title":"Heroïne","short":"Heroïne is een semisynthetisch opioïd met een snel en sterk euforisch effect en een groot verslavend potentieel.","definition":"<p><strong>Heroïne</strong> (diacetylmorfine) wordt in het lichaam omgezet in morfine. Een overdosis geeft miosis, bewustzijnsdaling en ademhalingsdepressie; het antidotum is naloxon. Onttrekking geeft grieperige klachten, onrust, verwijde pupillen en diarree. Behandeling o.a. met methadon of buprenorfine.</p>","image_url":"","wiki_title":"Heroin","match":"heroïne|heroine","option_only":true},"methadon":{"title":"Methadon","short":"Methadon is een langwerkend opioïd dat wordt gebruikt bij opioïdverslaving en bij pijn.","definition":"<p><strong>Methadon</strong> heeft een lange en per persoon wisselende halfwaardetijd, waardoor het onttrekkingsverschijnselen en craving voorkomt. Het wordt ook bij moeilijk behandelbare pijn gebruikt (NMDA-antagonisme). Risico's zijn accumulatie, ademhalingsdepressie en QT-verlenging.</p>","image_url":"","wiki_title":"Methadone","match":"methadon|methadone","option_only":true},"fentanyl":{"title":"Fentanyl","short":"Fentanyl is een zeer krachtig synthetisch opioïd, o.a. als pleister of intraveneus gebruikt.","definition":"<p><strong>Fentanyl</strong> is ongeveer 100 keer zo krachtig als morfine. Als pleister geeft het een gelijkmatige afgifte over drie dagen bij chronische pijn. Het wordt via de lever (CYP3A4) afgebroken en is daardoor bruikbaar bij nierfalen. Illegaal gebruik veroorzaakt veel overdoseringen.</p>","image_url":"","wiki_title":"Fentanyl","match":"fentanyl","option_only":true},"alprazolam":{"title":"Alprazolam","short":"Alprazolam is een kortwerkend benzodiazepine met een sterk anxiolytisch effect en een groot risico op afhankelijkheid.","definition":"<p><strong>Alprazolam</strong> werkt snel en kort, wat bijdraagt aan een groot risico op gewenning, afhankelijkheid en onttrekkingsverschijnselen tussen doses. Het wordt daarom terughoudend gebruikt.</p>","image_url":"","wiki_title":"Alprazolam","match":"alprazolam","option_only":true},"chloordiazepoxide":{"title":"Chloordiazepoxide","short":"Chloordiazepoxide is een langwerkend benzodiazepine, vooral gebruikt bij de behandeling van alcoholonttrekking.","definition":"<p><strong>Chloordiazepoxide</strong> heeft actieve metabolieten met een lange halfwaardetijd, wat een geleidelijke afbouw mogelijk maakt. Bij alcoholonttrekking voorkomt het insulten en een delirium tremens; bij leverfalen heeft oxazepam de voorkeur.</p>","image_url":"","wiki_title":"Chlordiazepoxide","match":"chloordiazepoxide","option_only":true},"amfetamine":{"title":"Amfetamine","short":"Amfetamine is een stimulerend middel dat de afgifte van dopamine en noradrenaline verhoogt.","definition":"<p><strong>Amfetaminen</strong> geven alertheid, euforie, verminderde eetlust en slaapbehoefte. Bijwerkingen en risico's: tachycardie, hypertensie, hyperthermie, agitatie en bij hoge of chronische doses een psychose. In therapeutische vorm (dexamfetamine, methylfenidaat) worden verwante middelen gebruikt bij ADHD en narcolepsie.</p>","image_url":"","wiki_title":"Amphetamine","match":"amfetamine|speed|methylfenidaat","option_only":true},"galactorroe":{"title":"Galactorroe","short":"Galactorroe is melkafscheiding uit de tepel buiten zwangerschap en borstvoeding.","definition":"<p><strong>Galactorroe</strong> ontstaat meestal door een verhoogd prolactine: een prolactinoom, dopamineblokkerende medicatie (antipsychotica, metoclopramide), hypothyreoïdie (TRH stimuleert prolactine) of druk op de hypofysesteel. Het gaat vaak samen met cyclusstoornissen en verminderd libido.</p>","image_url":"","wiki_title":"Galactorrhea","match":"galactorroe|galactorrhoea","option_only":true},"benzodiazepines":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"benzodiazepines","option_only":true},"tic stoornis":{"title":"Ticstoornis","short":"Een ticstoornis kenmerkt zich door plotselinge, snelle, herhaalde bewegingen of klanken die moeilijk te onderdrukken zijn.","definition":"<p><strong>Tics</strong> kunnen motorisch (knipperen, grimassen) of vocaal (keelschrapen, woorden) zijn en worden vaak voorafgegaan door een drang. Ze beginnen meestal in de kindertijd en nemen vaak af na de puberteit. Bij het <em>syndroom van Gilles de la Tourette</em> zijn er meerdere motorische en minstens één vocale tic, langer dan een jaar; vaak met ADHD of OCS.</p>","image_url":"","wiki_title":"Tic disorder","match":"tic stoornis","option_only":true},"illusoire vervalsing":{"title":"Illusionaire vervalsing","short":"Een illusionaire vervalsing (illusie) is het verkeerd waarnemen van een werkelijk bestaande prikkel, bijvoorbeeld een jas aan de kapstok aanzien voor een persoon.","definition":"<p>Een <strong>illusionaire vervalsing</strong> is een waarnemingsstoornis waarbij een <em>bestaande</em> prikkel verkeerd wordt geïnterpreteerd: een schaduw wordt een gestalte, het geruis van de verwarming klinkt als stemmen.</p><p>Het verschilt van een hallucinatie, waarbij iets wordt waargenomen zonder dat er een prikkel is. Illusies komen voor bij vermoeidheid, angst, delier en in schemerlicht, ook bij gezonde mensen.</p>","image_url":"","wiki_title":"","match":"illusoire vervalsing","option_only":true},"een corticosteroïd":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"een corticosteroïd","option_only":true},"autisme spectrumstoornis":{"title":"Autismespectrumstoornis","short":"Autismespectrumstoornis is een neurologische ontwikkelingsstoornis met beperkingen in sociale communicatie en beperkte, repetitieve gedragspatronen en interesses.","definition":"<p>Bij een <strong>autismespectrumstoornis</strong> zijn er vanaf de vroege ontwikkeling problemen met sociaal-emotionele wederkerigheid, non-verbale communicatie en het aangaan van relaties, gecombineerd met stereotiep gedrag, star vasthouden aan routines, beperkte interesses en afwijkende reacties op zintuiglijke prikkels. Het verloop en de ernst variëren sterk; er is een grote erfelijke component.</p>","image_url":"","wiki_title":"Autism spectrum","match":"autisme spectrumstoornis","option_only":true},"posttraumatische stress stoornis":{"title":"Posttraumatische stressstoornis (PTSS)","short":"PTSS ontstaat na een schokkende gebeurtenis, met herbelevingen, vermijding, negatieve stemming en verhoogde prikkelbaarheid.","definition":"<p>Bij <strong>PTSS</strong> duren de klachten langer dan een maand: herbelevingen (nachtmerries, flashbacks), vermijding van herinneringen, negatieve veranderingen in denken en stemming, en verhoogde waakzaamheid en schrikreacties. Behandeling met traumagerichte therapie (EMDR, cognitieve gedragstherapie), eventueel SSRI's.</p>","image_url":"","wiki_title":"Posttraumatic stress disorder","match":"posttraumatische stress stoornis","option_only":true},"bipolaire stemmingsstoornis":{"title":"Bipolaire stoornis","short":"Bij een bipolaire stoornis wisselen depressieve episoden af met manische (type I) of hypomane (type II) episoden.","definition":"<p>Een <strong>manie</strong> kenmerkt zich door een verhoogde of prikkelbare stemming, minder slaapbehoefte, gedachtevlucht, grootheidsideeën en risicovol gedrag, soms met psychotische kenmerken. Stemmingsstabilisatoren zoals lithium, valproaat en lamotrigine en sommige antipsychotica worden gebruikt; antidepressiva alleen kunnen een manie uitlokken.</p>","image_url":"","wiki_title":"Bipolar disorder","match":"bipolaire stemmingsstoornis","option_only":true},"bipolaire stoornissen":{"title":"Bipolaire stoornis","short":"Bij een bipolaire stoornis wisselen depressieve episoden af met manische (type I) of hypomane (type II) episoden.","definition":"<p>Een <strong>manie</strong> kenmerkt zich door een verhoogde of prikkelbare stemming, minder slaapbehoefte, gedachtevlucht, grootheidsideeën en risicovol gedrag, soms met psychotische kenmerken. Stemmingsstabilisatoren zoals lithium, valproaat en lamotrigine en sommige antipsychotica worden gebruikt; antidepressiva alleen kunnen een manie uitlokken.</p>","image_url":"","wiki_title":"Bipolar disorder","match":"bipolaire stoornissen","option_only":true},"ecstasy":{"title":"Ecstasy (MDMA)","short":"Ecstasy (MDMA) is een stimulerende drug die vooral serotonine (en dopamine, noradrenaline) laat vrijkomen.","definition":"<p><strong>MDMA</strong> geeft euforie, verbondenheid en energie. Risico's zijn hyperthermie, uitdroging of juist hyponatriëmie (door veel water drinken en ADH-afgifte), serotoninesyndroom, hartritmestoornissen en zelden leverfalen. Na gebruik kan een tijdelijke somberheid optreden.</p>","image_url":"","wiki_title":"MDMA","match":"ecstasy","option_only":true},"alzheimerdementie":{"title":"Ziekte van Alzheimer","short":"De ziekte van Alzheimer is de meest voorkomende oorzaak van dementie, met geleidelijk verlies van vooral het episodisch geheugen.","definition":"<p>Bij <strong>Alzheimer</strong> stapelen zich amyloïdplaques en neurofibrillaire tangles (tau) op, met verlies van neuronen, beginnend in de mediale temporaalkwab. Later volgen problemen met taal, oriëntatie, uitvoerende functies en gedrag. Cholinesteraseremmers en memantine geven een bescheiden symptomatisch effect.</p>","image_url":"","wiki_title":"Alzheimer's disease","match":"alzheimerdementie","option_only":true},"borderline persoonlijkheidsstoornis":{"title":"Borderline-persoonlijkheidsstoornis","short":"De borderline-persoonlijkheidsstoornis kenmerkt zich door instabiliteit in relaties, zelfbeeld en emoties, en impulsiviteit.","definition":"<p>Kenmerken zijn angst om verlaten te worden, intense en wisselende relaties, een instabiel zelfbeeld, impulsiviteit, terugkerende zelfbeschadiging of suïcidaliteit, stemmingswisselingen, chronische leegte, woede-uitbarstingen en kortdurende paranoïde ideeën bij stress. Behandeling met psychotherapie (bijv. DGT, MBT, schematherapie).</p>","image_url":"","wiki_title":"Borderline personality disorder","match":"borderline persoonlijkheidsstoornis","option_only":true},"nagebootste stoornis":{"title":"Nagebootste stoornis","short":"Bij een nagebootste stoornis veinst of veroorzaakt iemand opzettelijk ziekteverschijnselen om de patiëntenrol te krijgen.","definition":"<p>Bij de <strong>nagebootste stoornis</strong> (vroeger syndroom van Münchhausen) ontbreekt een uitwendig voordeel, anders dan bij simulatie. Er bestaat ook een vorm waarbij symptomen bij een ander (vaak een kind) worden opgewekt.</p>","image_url":"","wiki_title":"Factitious disorder","match":"nagebootste stoornis|syndroom van münchhausen","option_only":true},"striatum":{"title":"Striatum","short":"Het striatum (nucleus caudatus en putamen) is het belangrijkste inputstation van de basale kernen.","definition":"<p>Het <strong>striatum</strong> ontvangt projecties uit vrijwel de hele cortex en dopaminerge input uit de substantia nigra. Via de directe en indirecte route stuurt het de output van de basale kernen. Het ventrale deel (nucleus accumbens) speelt een rol bij beloning en motivatie.</p>","image_url":"","wiki_title":"Striatum","match":"striatum|corpus striatum","option_only":true},"eetbuistoornis":{"title":"Eetbuistoornis","short":"Bij een eetbuistoornis zijn er regelmatige eetbuien met controleverlies, zonder compensatiegedrag zoals braken.","definition":"<p>Bij de <strong>eetbuistoornis</strong> eet iemand in korte tijd veel, met controleverlies en daarna schaamte. Er wordt niet gecompenseerd, waardoor vaak overgewicht ontstaat. Behandeling vooral met cognitieve gedragstherapie.</p>","image_url":"","wiki_title":"Binge eating disorder","match":"eetbuistoornis|binge eating disorder","option_only":true},"een nagebootste stoornis":{"title":"Nagebootste stoornis","short":"Bij een nagebootste stoornis veinst of veroorzaakt iemand opzettelijk ziekteverschijnselen om de patiëntenrol te krijgen.","definition":"<p>Bij de <strong>nagebootste stoornis</strong> (vroeger syndroom van Münchhausen) ontbreekt een uitwendig voordeel, anders dan bij simulatie. Er bestaat ook een vorm waarbij symptomen bij een ander (vaak een kind) worden opgewekt.</p>","image_url":"","wiki_title":"Factitious disorder","match":"een nagebootste stoornis","option_only":true},"ventrale striatum":{"title":"Striatum","short":"Het striatum (nucleus caudatus en putamen) is het belangrijkste inputstation van de basale kernen.","definition":"<p>Het <strong>striatum</strong> ontvangt projecties uit vrijwel de hele cortex en dopaminerge input uit de substantia nigra. Via de directe en indirecte route stuurt het de output van de basale kernen. Het ventrale deel (nucleus accumbens) speelt een rol bij beloning en motivatie.</p>","image_url":"","wiki_title":"Striatum","match":"ventrale striatum","option_only":true},"hyperthermie":{"title":"Hyperthermie","short":"Bij hyperthermie stijgt de lichaamstemperatuur doordat warmteproductie of -opname groter is dan de warmteafgifte, zonder verhoogd setpoint.","definition":"<p>Anders dan bij koorts is het setpoint bij <strong>hyperthermie</strong> niet verhoogd, zodat koortsremmers niet helpen. Oorzaken: hitteberoerte, inspanning in de hitte, maligne hyperthermie (na bepaalde anesthetica), het maligne neurolepticasyndroom, serotoninesyndroom en drugs (MDMA, cocaïne). Behandeling: actief koelen.</p>","image_url":"","wiki_title":"Hyperthermia","match":"hyperthermie|oververhitting|hitteberoerte","option_only":true},"antidepressiva":{"title":"Antidepressiva","short":"Antidepressiva zijn geneesmiddelen tegen depressie en angststoornissen, die vooral de serotonerge en noradrenerge overdracht beïnvloeden.","definition":"<p>Groepen zijn SSRI's (bijv. sertraline, citalopram), SNRI's (venlafaxine, duloxetine), tricyclische antidepressiva, mirtazapine en MAO-remmers. Het effect treedt na 2–6 weken op. Bij jongeren kan in het begin de suïcidaliteit toenemen; abrupt stoppen geeft onttrekkingsverschijnselen.</p>","image_url":"","wiki_title":"Antidepressant","match":"antidepressiva|antidepressivum","option_only":true},"hyperkaliumie":{"title":"Hyperkaliëmie","short":"Hyperkaliëmie is een te hoog kalium in het bloed; gevaarlijk door het risico op hartritmestoornissen.","definition":"<p><strong>Hyperkaliëmie</strong> ontstaat door verminderde uitscheiding (nierfalen, ACE-remmers, ARB's, kaliumsparende diuretica, hypoaldosteronisme), verschuiving uit de cel (acidose, insulinetekort, celafbraak) of overmatige inname. Op het ECG ziet men spitse T-toppen, verbrede QRS-complexen en uiteindelijk ventrikelfibrilleren. Acute behandeling: calciumgluconaat (membraanstabilisatie), insuline met glucose en salbutamol, en kalium verwijderen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"hyperkaliumie","option_only":true},"propranolol":{"title":"Propranolol","short":"Propranolol is een niet-selectieve, lipofiele bètablokker, gebruikt o.a. bij tremor, migraineprofylaxe, angstklachten, hyperthyreoïdie en portale hypertensie.","definition":"<p>Doordat <strong>propranolol</strong> ook β2-receptoren blokkeert, kan het bronchospasme geven en is het gecontra-indiceerd bij astma. Het werkt goed tegen lichamelijke angstverschijnselen (trillen, hartkloppingen) en tegen infantiele hemangiomen bij baby's.</p>","image_url":"","wiki_title":"Propranolol","match":"propranolol","option_only":true},"fluoxetine":{"title":"Fluoxetine","short":"Fluoxetine is een SSRI met een zeer lange halfwaardetijd; gebruikt bij depressie, OCS en boulimia nervosa.","definition":"<p>Door de lange halfwaardetijd van <strong>fluoxetine</strong> en zijn actieve metaboliet zijn er weinig onttrekkingsverschijnselen, maar blijven interacties lang bestaan. Het is een sterke remmer van CYP2D6. Bij kinderen en jongeren met depressie is het het best onderzochte antidepressivum.</p>","image_url":"","wiki_title":"Fluoxetine","match":"fluoxetine|prozac","option_only":true},"nicotine":{"title":"Nicotine","short":"Nicotine is de verslavende stof in tabak; het stimuleert nicotinerge acetylcholinereceptoren en laat dopamine vrijkomen in het beloningssysteem.","definition":"<p><strong>Nicotine</strong> zelf veroorzaakt de verslaving, maar de schade van roken komt vooral van andere stoffen in de rook (teer, CO, kankerverwekkende stoffen). Nicotinevervangende middelen (pleisters, kauwgom) verdubbelen ongeveer de kans op succesvol stoppen.</p>","image_url":"","wiki_title":"Nicotine","match":"nicotine|nicotinevervanging","option_only":true},"schizofrenie":{"title":"Schizofrenie","short":"Schizofrenie is een psychotische stoornis met wanen, hallucinaties en gedesorganiseerd denken, plus negatieve symptomen, gedurende minstens zes maanden.","definition":"<p>Bij <strong>schizofrenie</strong> zijn er positieve symptomen (wanen, hallucinaties, desorganisatie), negatieve symptomen (vervlakking, initiatiefverlies, terugtrekking) en cognitieve problemen. Het begint meestal in de late adolescentie of jongvolwassenheid. Risicofactoren zijn erfelijkheid, cannabis, opgroeien in de stad en migratie. Behandeling met antipsychotica en psychosociale ondersteuning.</p>","image_url":"","wiki_title":"Schizophrenia","match":"schizofrenie","option_only":true},"somatisatie":{"title":"Somatisatie","short":"Somatisatie is de neiging om psychische spanning te ervaren en te uiten als lichamelijke klachten.","definition":"<p>Bij een <strong>somatisch-symptoomstoornis</strong> zijn er lichamelijke klachten die veel zorgen, gedachten en gedrag oproepen en het functioneren beperken, ongeacht of er een medische verklaring is. Behandeling richt zich op uitleg, het doorbreken van vicieuze cirkels en geleidelijk opbouwen van activiteiten, vaak met cognitieve gedragstherapie.</p>","image_url":"","wiki_title":"Somatic symptom disorder","match":"somatisatie|somatisch-symptoomstoornis|een somatisch-symptoomstoornis|somatisch onvoldoende verklaarde klachten","option_only":true},"fobische stoornis":{"title":"Specifieke fobie","short":"Een specifieke fobie is een overmatige angst voor een bepaald object of een situatie, zoals spinnen, hoogte of injecties, met vermijding.","definition":"<p>Bij een <strong>specifieke fobie</strong> weet de persoon meestal dat de angst overdreven is. Bloed-injectie-letselfobie is bijzonder doordat het een vasovagale flauwte kan geven. Exposuretherapie is zeer effectief.</p>","image_url":"","wiki_title":"Specific phobia","match":"fobische stoornis|specifieke fobie|fobieën|fobie","option_only":true},"prevalentie":{"title":"Prevalentie","short":"Prevalentie is het aantal bestaande gevallen van een ziekte in een populatie op een bepaald moment of in een periode.","definition":"<p>De <strong>prevalentie</strong> hangt af van de incidentie (nieuwe gevallen) en de ziekteduur: prevalentie ≈ incidentie × duur. Een betere behandeling die mensen langer in leven houdt zonder ze te genezen, verhoogt dus de prevalentie. De voorspellende waarde van een test hangt sterk af van de prevalentie.</p>","image_url":"","wiki_title":"Prevalence","match":"prevalentie|puntprevalentie","option_only":true},"lichttherapie":{"title":"Lichttherapie","short":"Lichttherapie gebruikt licht ter behandeling: UV-licht bij huidziekten of fel licht bij winterdepressie en slaapritmestoornissen.","definition":"<p>Bij <strong>huidziekten</strong> (psoriasis, eczeem, vitiligo) wordt smalspectrum-UVB of PUVA gebruikt, met op lange termijn een verhoogd risico op huidkanker. Bij een <strong>seizoensgebonden depressie</strong> helpt dagelijkse blootstelling aan fel licht in de ochtend.</p>","image_url":"","wiki_title":"Light therapy","match":"lichttherapie|uvb-therapie|smalspectrum uvb fototherapie","option_only":true},"faalangst":{"title":"Faalangst","short":"Faalangst is angst om te falen in situaties waarin iemand wordt beoordeeld, met spanning, blokkeren en vermijding.","definition":"<p>Bij <strong>faalangst</strong> kan iemand door spanning slechter presteren dan hij kan, wat de angst weer versterkt. Het hangt samen met perfectionisme en negatieve gedachten. Cognitieve gedragstherapie en training helpen.</p>","image_url":"","wiki_title":"","match":"faalangst|prestatieangst","option_only":true},"problematische hechting":{"title":"Hechtingsproblematiek","short":"Bij een problematische hechting heeft een kind geen veilige band met een verzorger kunnen opbouwen, met gevolgen voor emotionele en sociale ontwikkeling.","definition":"<p>Volgens de <strong>hechtingstheorie</strong> (Bowlby, Ainsworth) ontwikkelen kinderen een veilige of onveilige (vermijdende, ambivalente, gedesorganiseerde) hechtingsstijl, afhankelijk van de sensitiviteit van verzorgers. Ernstige verwaarlozing kan een reactieve hechtingsstoornis geven.</p>","image_url":"","wiki_title":"Attachment disorder","match":"problematische hechting|hechtingsstoornis|onveilige hechting","option_only":true},"pregabaline":{"title":"Pregabaline","short":"Pregabaline is een middel tegen neuropathische pijn, epilepsie en gegeneraliseerde angst; het remt calciumkanalen in zenuwuiteinden.","definition":"<p><strong>Pregabaline</strong> en gabapentine binden aan de α2δ-subeenheid van calciumkanalen en verminderen de afgifte van prikkelende neurotransmitters. Bijwerkingen: sufheid, duizeligheid en oedeem; er is risico op misbruik en afhankelijkheid. Bij nierfunctiestoornis is een lagere dosis nodig.</p>","image_url":"","wiki_title":"Pregabalin","match":"pregabaline|gabapentine","option_only":true},"neutropenie":{"title":"Neutropenie","short":"Neutropenie is een te laag aantal neutrofielen in het bloed, met een verhoogd risico op bacteriële en schimmelinfecties.","definition":"<p>Oorzaken van <strong>neutropenie</strong> zijn o.a. chemotherapie, geneesmiddelen (bijv. clozapine, thyreostatica, metamizol: agranulocytose), virale infecties, beenmergziekten, vitamine B12-tekort en auto-immuniteit. Bij een aantal onder 0,5 × 10⁹/L is koorts een spoedgeval.</p>","image_url":"","wiki_title":"Neutropenia","match":"neutropenie|agranulocytose","option_only":true},"putamen":{"title":"Putamen","short":"Het putamen is een kern van de basale ganglia die samen met de nucleus caudatus het striatum vormt.","definition":"<p>Het <strong>putamen</strong> ontvangt vooral input uit de motorische cortex en speelt een rol in de motoriek. Het ligt lateraal van de globus pallidus; samen heten ze de nucleus lentiformis. Hypertensieve bloedingen ontstaan vaak in het putamen.</p>","image_url":"","wiki_title":"Putamen","match":"putamen","option_only":true},"globus pallidus":{"title":"Globus pallidus","short":"De globus pallidus is een kern van de basale ganglia met een externe en interne kern, die vooral remmende (GABA-erge) output geeft.","definition":"<p>De <strong>globus pallidus interna</strong> is samen met de substantia nigra pars reticulata de uitgangskern van de basale ganglia; de externa is een schakel in de indirecte route.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus","option_only":true},"wgbo":{"title":"WGBO (Wet op de geneeskundige behandelingsovereenkomst)","short":"De WGBO regelt de rechten en plichten van patiënt en hulpverlener bij een medische behandeling.","definition":"<p>Onder de <strong>WGBO</strong> vallen o.a. het recht op informatie, toestemming (informed consent), het medisch dossier (inzage, bewaartermijn) en het beroepsgeheim. Bij wilsonbekwame patiënten beslist een vertegenwoordiger. Voor kinderen gelden leeftijdsgrenzen (12 en 16 jaar).</p>","image_url":"","wiki_title":"","match":"wgbo|wet geneeskundige behandelovereenkomst|wet op de geneeskundige behandelingsovereenkomst","option_only":true},"mri scan":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri scan","option_only":true},"achterdocht":{"title":"Achterdocht (paranoïdie)","short":"Overmatig wantrouwen jegens de bedoelingen van anderen, kan uitgroeien tot paranoïde wanen.","definition":"<p><b>Achterdocht</b> of <b>paranoïdie</b> is een overmatig, onterecht wantrouwen tegenover de intenties van anderen, bijvoorbeeld het idee dat buren samenspannen. Het is een cognitief symptoom dat kan uitgroeien tot een paranoïde waan bij psychose.</p>","image_url":"","wiki_title":"Paranoia","match":"achterdocht","option_only":true},"specifieke serotonineheropnameremmer (ssri)":{"title":"SSRI","short":"Selectieve serotonineheropnameremmer; antidepressivum dat ook een trombocytopathie kan veroorzaken.","definition":"<p>Een <b>SSRI</b> (selectieve serotonineheropnameremmer) is een veelgebruikt antidepressivum. SSRI’s remmen de heropname van serotonine, ook in de bloedplaatjes, waardoor een <b>trombocytopathie</b> ontstaat en het risico op maag-/bloedingscomplicaties toeneemt, zeker samen met NSAIDs.</p>","image_url":"","wiki_title":"Selective serotonin reuptake inhibitor","match":"specifieke serotonineheropnameremmer (ssri)","option_only":true},"lithium":{"title":"Lithium","short":"Stemmingsstabilisator bij bipolaire stoornis; kan als bijwerking nefrogene diabetes insipidus geven.","definition":"<p><b>Lithium</b> is een stemmingsstabilisator bij de bipolaire stoornis. Een belangrijke bijwerking is <b>nefrogene diabetes insipidus</b>: de nier reageert onvoldoende op ADH, met polyurie en polydipsie als gevolg.</p>","image_url":"","wiki_title":"Lithium (medication)","match":"lithium","option_only":true},"substantia nigra":{"title":"Substantia nigra","short":"Dopaminerge kern in het mesencephalon, deel van de basale ganglia.","definition":"<p>De <b>substantia nigra</b> zendt dopaminerge projecties naar het striatum; degeneratie leidt tot de ziekte van Parkinson.</p>","image_url":"","wiki_title":"Substantia nigra","match":"substantia nigra","option_only":true},"surmenage":{"title":"Surmenage","short":"Overbelasting door aanhoudende stress; nauw verwant aan overspanning en aanpassingsstoornis.","definition":"<p><b>Surmenage</b> is een toestand van overbelasting door langdurige of overmatige (psychische) inspanning en stress, waarbij lichamelijke en psychische klachten optreden. De term overlapt met overspanning en aanpassingsstoornis.</p>","image_url":"","wiki_title":"","match":"surmenage","option_only":true},"varenicline":{"title":"Varenicline","short":"Partiële agonist van de α4β2-nicotine-acetylcholinereceptor.","definition":"<p><strong>Varenicline</strong> stimuleert de nicotinereceptor gedeeltelijk en verdringt tegelijk nicotine van de receptor. Bijwerkingen zijn misselijkheid, levendige dromen en slaapstoornissen.</p>","image_url":"","wiki_title":"Varenicline","match":"varenicline","option_only":true},"acamprosaat":{"title":"Acamprosaat","short":"Middel dat de craving (hunkering) naar alcohol vermindert; werkt vermoedelijk via antagonisme van glutamaatreceptoren.","definition":"<p><strong>Acamprosaat</strong> wordt gebruikt om de kans op terugval bij alcoholverslaving te verkleinen door de hunkering (craving) naar alcohol te verminderen. Het werkingsmechanisme berust vermoedelijk op modulatie/antagonisme van glutamaterge (NMDA-)neurotransmissie, waardoor de bij onthouding ontstane glutamaat-overactiviteit wordt gedempt.</p>","image_url":"","wiki_title":"Acamprosate","match":"acamprosaat","option_only":true},"risperidone":{"title":"Risperidon","short":"Atypisch antipsychoticum; kan door dopamineblokkade prolactinestijging met lactatie en libidoverlies geven.","definition":"<p><strong>Risperidon</strong> is een atypisch antipsychoticum dat onder meer dopamine-D2-receptoren blokkeert. Blokkade in de tubero-infundibulaire baan verhoogt prolactine, wat kan leiden tot lactatie, menstruatiestoornissen en libidoverlies. Verkrijgbaar als depotpreparaat.</p>","image_url":"","wiki_title":"Risperidone","match":"risperidone","option_only":true},"moclobemide":{"title":"Moclobemide","short":"Moclobemide is een reversibele MAO-A-remmer die de afbraak van monoamines zoals noradrenaline remt.","definition":"<p><b>Moclobemide</b> is een reversibele remmer van monoamine oxidase A (RIMA), gebruikt als antidepressivum. Door remming van MAO neemt de afbraak van noradrenaline (en andere monoamines) af.</p>","image_url":"","wiki_title":"Moclobemide","match":"moclobemide","option_only":true},"betablokkers":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"betablokkers","option_only":true},"cingulaire cortex":{"title":"Cingulaire cortex","short":"Deel van de mediale cortex, betrokken bij emotie en het limbische systeem.","definition":"<p>De <b>cingulaire cortex</b> ligt boven het corpus callosum en maakt deel uit van het limbische systeem.</p>","image_url":"","wiki_title":"Cingulate cortex","match":"cingulaire cortex","option_only":true},"antisociale persoonlijkheidsstoornis":{"title":"Antisociale persoonlijkheidsstoornis","short":"Cluster B-persoonlijkheidsstoornis met een patroon van minachting voor en schending van de rechten van anderen.","definition":"<p>De <strong>antisociale persoonlijkheidsstoornis</strong> wordt gekenmerkt door een doorgaand patroon van het negeren en schenden van de rechten van anderen, met impulsiviteit, prikkelbaarheid, gebrek aan berouw en normoverschrijdend gedrag. Ze valt onder cluster B.</p>","image_url":"","wiki_title":"Antisocial personality disorder","match":"antisociale persoonlijkheidsstoornis","option_only":true},"persisterende depressieve stoornis":{"title":"Persisterende depressieve stoornis (dysthymie)","short":"Chronisch sombere stemming die het grootste deel van de dag aanwezig is gedurende minstens twee jaar (bij kinderen een jaar).","definition":"<p>De <strong>persisterende depressieve stoornis (dysthymie)</strong> is een chronische stemmingsstoornis met een gedrukte stemming gedurende het merendeel van de dag, meer dagen wel dan niet, gedurende minstens twee jaar (bij kinderen en adolescenten minstens één jaar). Bijkomende klachten zijn onder meer slaap- en eetstoornissen, weinig energie en concentratieproblemen.</p>","image_url":"","wiki_title":"Dysthymia","match":"persisterende depressieve stoornis","option_only":true},"disulfiram":{"title":"Disulfiram (Antabus®)","short":"Middel bij alcoholverslaving dat de afbraak van alcohol remt (aldehydedehydrogenase), waardoor bij drinken een zeer onaangename reactie ontstaat.","definition":"<p><strong>Disulfiram</strong> remt het enzym aldehydedehydrogenase, waardoor bij alcoholgebruik aceetaldehyde ophoopt en een heftige, onaangename reactie (blozen, misselijkheid, hartkloppingen) ontstaat. Zo werkt het als aversiemiddel bij alcoholverslaving door remming van het metabolisme van alcohol.</p>","image_url":"","wiki_title":"Disulfiram","match":"disulfiram","option_only":true},"narcistische persoonlijkheidsstoornis":{"title":"Narcistische persoonlijkheidsstoornis","short":"Persoonlijkheidsstoornis met een patroon van grandiositeit, behoefte aan bewondering en gebrek aan empathie.","definition":"<p>De <strong>narcistische persoonlijkheidsstoornis</strong> kenmerkt zich door een doorgaand patroon van grandiositeit (in fantasie of gedrag), een sterke behoefte aan bewondering en een gebrek aan empathie. Ze behoort tot cluster B van de persoonlijkheidsstoornissen.</p>","image_url":"","wiki_title":"Narcissistic personality disorder","match":"narcistische persoonlijkheidsstoornis","option_only":true},"oppositioneel opstandige (gedrags)stoornis":{"title":"Oppositioneel-opstandige stoornis (ODD)","short":"Gedragsstoornis bij kinderen met een patroon van boze/prikkelbare stemming, opstandig gedrag en wraakzucht tegenover gezagsfiguren.","definition":"<p>De <strong>oppositioneel-opstandige stoornis (ODD)</strong> is een gedragsstoornis met een aanhoudend patroon van prikkelbare/boze stemming, ruziënd en tegendraads gedrag en wraakzucht, vooral gericht op gezagsfiguren. Bij kinderen met ODD stijgt de cortisolspiegel bij stress minder dan normaal.</p>","image_url":"","wiki_title":"Oppositional defiant disorder","match":"oppositioneel opstandige (gedrags)stoornis","option_only":true},"autisme spectrum stoornis":{"title":"Autismespectrumstoornis","short":"Autismespectrumstoornis is een neurologische ontwikkelingsstoornis met beperkingen in sociale communicatie en beperkte, repetitieve gedragspatronen en interesses.","definition":"<p>Bij een <strong>autismespectrumstoornis</strong> zijn er vanaf de vroege ontwikkeling problemen met sociaal-emotionele wederkerigheid, non-verbale communicatie en het aangaan van relaties, gecombineerd met stereotiep gedrag, star vasthouden aan routines, beperkte interesses en afwijkende reacties op zintuiglijke prikkels. Het verloop en de ernst variëren sterk; er is een grote erfelijke component.</p>","image_url":"","wiki_title":"Autism spectrum","match":"autisme spectrum stoornis","option_only":true},"apathie":{"title":"Apathie","short":"Verlies van motivatie, initiatief en interesse, zonder dat de patiënt dit zelf als lijden ervaart; veel voorkomend bij dementie en depressie.","definition":"<p><strong>Apathie</strong> is een toestand van verminderde motivatie, initiatiefverlies en emotionele vervlakking. Bij dementie is apathie vaak de grootste belasting voor mantelzorgers.</p>","image_url":"","wiki_title":"Apathy","match":"apathie","option_only":true},"hallucinaties":{"title":"Hallucinaties","short":"Zintuiglijke waarnemingen zonder externe prikkel, bijv. stemmen horen; kenmerkend voor psychose.","definition":"<p><b>Hallucinaties</b> zijn waarnemingen zonder werkelijke prikkel, bijvoorbeeld het horen van stemmen. Ze zijn een kernsymptoom van <b>psychose</b>.</p>","image_url":"","wiki_title":"Hallucination","match":"hallucinaties","option_only":true},"atypische depressie":{"title":"atypische depressie","short":"Subtype depressie met stemmingsreactiviteit en ‘omgekeerde’ vegetatieve symptomen: veel slapen, toegenomen eetlust/gewicht, loodzwaar gevoel en gevoeligheid voor afwijzing.","definition":"<p>De <strong>atypische depressie</strong> onderscheidt zich door stemmingsreactiviteit (opklaren bij positieve gebeurtenissen) en ‘omgekeerde’ vegetatieve kenmerken: hypersomnie, toegenomen eetlust en gewicht, loodzwaar gevoel in de ledematen en een langdurige gevoeligheid voor interpersoonlijke afwijzing. Klassieke MAO-remmers zijn hierbij relatief effectief.</p>","image_url":"","wiki_title":"Atypical depression","match":"atypische depressie","option_only":true},"peri-partum depressie":{"title":"Peri-partumdepressie","short":"Depressieve episode die optreedt tijdens de zwangerschap of kort na de bevalling.","definition":"<p>Een <strong>peri-partumdepressie</strong> is een depressie in de periode rond de bevalling. Belangrijke voorspellers zijn onder andere neuroticisme bij de moeder en een ongewenste zwangerschap.</p>","image_url":"","wiki_title":"Postpartum depression","match":"peri-partum depressie","option_only":true},"afhankelijke persoonlijkheidsstoornis":{"title":"Afhankelijke persoonlijkheidsstoornis","short":"Cluster C-persoonlijkheidsstoornis met een buitensporige behoefte verzorgd te worden, onderdanig en klampend gedrag.","definition":"<p>De <strong>afhankelijke persoonlijkheidsstoornis</strong> (cluster C) betreft een overmatige behoefte aan steun en geruststelling, moeite zelfstandig beslissingen te nemen en angst om alleen te zijn.</p>","image_url":"","wiki_title":"","match":"afhankelijke persoonlijkheidsstoornis","option_only":true},"respons preventie":{"title":"Responspreventie","short":"Onderdeel van exposurebehandeling bij OCS: de patiënt stelt zich bloot aan de angstprikkel én laat het dwangmatige neutraliserende gedrag (ritueel) bewust achterwege.","definition":"<p><b>Responspreventie</b> betekent het achterwege laten van de compulsieve/neutraliserende handeling tijdens exposure. Bij exposure met responspreventie (ERP) leert de patiënt dat de gevreesde ramp uitblijft zonder het ritueel.</p>","image_url":"","wiki_title":"Exposure and response prevention","match":"respons preventie","option_only":true},"zolpidem":{"title":"Zolpidem","short":"Kortwerkend hypnoticum (Z-drug) dat aangrijpt op de GABA-A-receptor. Het hypnotische effect kan worden geantagoneerd met flumazenil.","definition":"<p><strong>Zolpidem</strong> is een niet-benzodiazepine slaapmiddel dat selectief bindt aan de α1-subunit van de GABA-A-receptor. Bij overdosis kan het effect worden opgeheven met de competitieve antagonist flumazenil.</p>","image_url":"","wiki_title":"Zolpidem","match":"zolpidem","option_only":true},"waanachtige gedachte":{"title":"Waanachtige gedachte","short":"Een overtuiging met waankarakter die (nog) niet volledig onwrikbaar is; de patiënt kan er soms nog enigszins afstand van nemen.","definition":"<p>Een <strong>waanachtige gedachte</strong> heeft de inhoud van een waan maar mist de volledige onwrikbaarheid; de patiënt twijfelt soms nog of laat zich deels corrigeren. Het is een minder uitgekristalliseerde vorm dan een echte waan.</p>","image_url":"","wiki_title":"","match":"waanachtige gedachte","option_only":true},"schizo-affectieve stoornis":{"title":"Schizoaffectieve stoornis","short":"Bij een schizoaffectieve stoornis komen psychotische symptomen van schizofrenie samen voor met episoden van depressie of manie.","definition":"<p>Voor de diagnose moeten er ook periodes van minstens twee weken met wanen of hallucinaties zonder stemmingsstoornis zijn geweest. Behandeling combineert antipsychotica met stemmingsstabilisatoren of antidepressiva.</p>","image_url":"","wiki_title":"Schizoaffective disorder","match":"schizo-affectieve stoornis","option_only":true},"somatisch-symptoom stoornis":{"title":"Somatisatie","short":"Somatisatie is de neiging om psychische spanning te ervaren en te uiten als lichamelijke klachten.","definition":"<p>Bij een <strong>somatisch-symptoomstoornis</strong> zijn er lichamelijke klachten die veel zorgen, gedachten en gedrag oproepen en het functioneren beperken, ongeacht of er een medische verklaring is. Behandeling richt zich op uitleg, het doorbreken van vicieuze cirkels en geleidelijk opbouwen van activiteiten, vaak met cognitieve gedragstherapie.</p>","image_url":"","wiki_title":"Somatic symptom disorder","match":"somatisch-symptoom stoornis","option_only":true},"post-traumatische stress-stoornis":{"title":"Posttraumatische stressstoornis (PTSS)","short":"PTSS ontstaat na een schokkende gebeurtenis, met herbelevingen, vermijding, negatieve stemming en verhoogde prikkelbaarheid.","definition":"<p>Bij <strong>PTSS</strong> duren de klachten langer dan een maand: herbelevingen (nachtmerries, flashbacks), vermijding van herinneringen, negatieve veranderingen in denken en stemming, en verhoogde waakzaamheid en schrikreacties. Behandeling met traumagerichte therapie (EMDR, cognitieve gedragstherapie), eventueel SSRI's.</p>","image_url":"","wiki_title":"Posttraumatic stress disorder","match":"post-traumatische stress-stoornis","option_only":true},"hormoontherapie":{"title":"Hormoontherapie","short":"Behandeling met (vrouwelijke) geslachtshormonen om overgangsklachten te verlichten.","definition":"<p>Bij hormoontherapie in de overgang worden oestrogenen (soms met progestageen) toegediend om klachten als opvliegers te verminderen. Er zijn afwegingen rond risico's en indicaties.</p>","image_url":"","wiki_title":"Hormone replacement therapy (menopause)","match":"hormoontherapie","option_only":true},"oppositioneel-opstandige gedragsstoornis":{"title":"Oppositioneel-opstandige gedragsstoornis (ODD)","short":"Kinderpsychiatrisch beeld met een patroon van boze/prikkelbare stemming, ruziënd en opstandig gedrag.","definition":"<p>De <strong>oppositioneel-opstandige gedragsstoornis (ODD)</strong> kenmerkt zich door een aanhoudend patroon van prikkelbaarheid, opstandigheid en dwars gedrag tegenover gezagsfiguren. De symptomen zijn minder ernstig dan bij de normoverschrijdend-gedragsstoornis; behandeling bestaat vooral uit oudertraining.</p>","image_url":"","wiki_title":"Oppositional defiant disorder","match":"oppositioneel-opstandige gedragsstoornis","option_only":true},"persoonlijkheidsstoornis":{"title":"Persoonlijkheidsstoornis","short":"Duurzaam, inflexibel patroon van beleven en gedrag dat afwijkt van de norm en lijden of disfunctioneren veroorzaakt.","definition":"<p>Een <strong>persoonlijkheidsstoornis</strong> is een duurzaam en star patroon van innerlijke ervaring en gedrag dat sterk afwijkt van de culturele verwachting en leidt tot lijden of beperkingen. In de DSM-5 worden clusters A (excentriek), B (dramatisch/impulsief) en C (angstig) onderscheiden. Persoonlijkheidsstoornissen komen vaak voor als comorbiditeit bij psychiatrische aandoeningen.</p>","image_url":"","wiki_title":"Personality disorder","match":"persoonlijkheidsstoornis","option_only":true},"selectieve serotonineheropnameremmers (ssri)":{"title":"SSRI","short":"Selectieve serotonineheropnameremmer; antidepressivum dat ook een trombocytopathie kan veroorzaken.","definition":"<p>Een <b>SSRI</b> (selectieve serotonineheropnameremmer) is een veelgebruikt antidepressivum. SSRI’s remmen de heropname van serotonine, ook in de bloedplaatjes, waardoor een <b>trombocytopathie</b> ontstaat en het risico op maag-/bloedingscomplicaties toeneemt, zeker samen met NSAIDs.</p>","image_url":"","wiki_title":"Selective serotonin reuptake inhibitor","match":"selectieve serotonineheropnameremmers (ssri)","option_only":true},"tricyclische antidepressiva (tca)":{"title":"Tricyclische antidepressiva","short":"Tricyclische antidepressiva remmen de heropname van noradrenaline en serotonine en hebben veel anticholinerge bijwerkingen.","definition":"<p><strong>TCA's</strong> (zoals amitriptyline, nortriptyline, clomipramine) worden gebruikt bij depressie en in lage dosis bij neuropathische pijn. Bijwerkingen: droge mond, obstipatie, urineretentie, sufheid, orthostatische hypotensie en gewichtstoename. Bij overdosering zijn ze gevaarlijk door natriumkanaalblokkade (breed QRS, aritmieën) en insulten.</p>","image_url":"","wiki_title":"Tricyclic antidepressant","match":"tricyclische antidepressiva (tca)","option_only":true},"cognitieve functies":{"title":"Cognitieve functies","short":"Verstandelijke functies zoals bewustzijn, aandacht, geheugen, denken en concentratie.","definition":"<p><b>Cognitieve functies</b> omvatten onder meer bewustzijn, oriëntatie, aandacht, concentratie, geheugen en het denken. Stoornissen hierin uiten zich bijvoorbeeld als verminderde concentratie of piekeren.</p>","image_url":"","wiki_title":"","match":"cognitieve functies","option_only":true},"affectieve functies":{"title":"Affectieve functies","short":"Functies die de stemming en gevoelens betreffen, zoals angst, somberheid en stemmingsschommelingen.","definition":"<p><b>Affectieve functies</b> betreffen de stemming en het gevoelsleven. Stoornissen hierin uiten zich als bijvoorbeeld angstige of sombere stemming, lusteloosheid of een labiel affect.</p>","image_url":"","wiki_title":"","match":"affectieve functies","option_only":true},"acute stressstoornis":{"title":"Acute stressstoornis","short":"Kortdurende stressreactie na een traumatische gebeurtenis, met o.a. herbelevingen en dissociatieve symptomen.","definition":"<p>Een <b>acute stressstoornis</b> ontstaat na een duidelijke traumatische gebeurtenis en kenmerkt zich door herbelevingen, vermijding en dissociatieve symptomen (derealisatie, depersonalisatie, dissociatieve amnesie) binnen enkele weken na het trauma.</p>","image_url":"","wiki_title":"Acute stress disorder","match":"acute stressstoornis","option_only":true},"obsessieve compulsieve stoornis":{"title":"Obsessies en compulsies (OCS)","short":"Bij een obsessieve-compulsieve stoornis zijn er dwanggedachten (obsessies) en/of dwanghandelingen (compulsies) die veel tijd kosten en lijden geven.","definition":"<p>Bij <strong>OCS</strong> roepen obsessies (bijv. over besmetting, schade, symmetrie) angst op, die met compulsies (wassen, controleren, ordenen, tellen) tijdelijk wordt verminderd. De persoon ziet meestal in dat de gedachten overdreven zijn. Behandeling met exposure en responspreventie en/of SSRI's.</p>","image_url":"","wiki_title":"Obsessive–compulsive disorder","match":"obsessieve compulsieve stoornis","option_only":true},"genderdysforie":{"title":"Genderdysforie","short":"Aanhoudend onwelbevinden door incongruentie tussen de ervaren genderidentiteit en het bij de geboorte toegewezen geslacht.","definition":"<p><strong>Genderdysforie</strong> is het lijden dat ontstaat door een discrepantie tussen de beleefde genderidentiteit en het toegewezen geslacht. Bij kinderen persisteert de dysforie lang niet altijd tot op latere leeftijd.</p>","image_url":"","wiki_title":"Gender dysphoria","match":"genderdysforie","option_only":true},"labiel affect":{"title":"Labiel affect","short":"Sterk wisselende, moeilijk te beheersen gevoelsuitingen.","definition":"<p>Een <b>labiel affect</b> is een snel wisselende en moeilijk te reguleren gevoelsuiting, waarbij iemand bijvoorbeeld gemakkelijk in huilen of boosheid uitbarst. Het wordt beoordeeld bij het psychiatrisch onderzoek.</p>","image_url":"","wiki_title":"","match":"labiel affect","option_only":true},"rumineren":{"title":"Rumineren","short":"Het herhaaldelijk en piekerend blijven stilstaan bij (negatieve) gedachten; onderscheiden van cognitieve functiestoornissen.","definition":"<p><strong>Rumineren</strong> is aanhoudend piekeren waarbij dezelfde (vaak sombere) gedachten steeds terugkeren. Het is een denkinhoud/proces en wordt in het psychiatrisch onderzoek niet gerekend tot de cognitieve functies zoals oriëntatie of praxis.</p>","image_url":"","wiki_title":"Rumination (psychology)","match":"rumineren","option_only":true},"anticipatieangst":{"title":"Anticipatieangst","short":"Angst voorafgaand aan een gevreesde situatie of aan het krijgen van een volgende paniekaanval.","definition":"<p><strong>Anticipatieangst</strong> is de angst die optreedt bij het vooruitdenken aan een gevreesde gebeurtenis of een mogelijke nieuwe paniekaanval. Deze verwachtingsangst kan zelf al klachten en vermijding uitlokken.</p>","image_url":"","wiki_title":"","match":"anticipatieangst","option_only":true},"somatische waan":{"title":"Somatische waan","short":"Onterechte, onwrikbare overtuiging over het eigen lichaam (bv. bestraald of aangetast worden), zonder feitelijke waarneming.","definition":"<p>Een <strong>somatische waan</strong> is een waanovertuiging die het lichaam betreft (bv. de overtuiging bestraald of vergiftigd te worden). Het betreft een stoornis in de <em>inhoud van het denken</em>, in tegenstelling tot een somatische hallucinatie (een lichamelijke gewaarwording zonder externe prikkel).</p>","image_url":"","wiki_title":"Delusion","match":"somatische waan","option_only":true},"burn-out":{"title":"Burn-out","short":"Toestand van overspanning die langer dan 6 maanden bestaat en waarbij moeheid en uitputting sterk op de voorgrond staan.","definition":"<p><b>Burn-out</b> vereist: (a) er is sprake van overspanning, (b) de klachten zijn meer dan 6 maanden geleden begonnen, en (c) gevoelens van moeheid en uitputting staan sterk op de voorgrond.</p>","image_url":"","wiki_title":"Occupational burnout","match":"burn-out","option_only":true},"ziekteangststoornis":{"title":"Ziekte-angststoornis","short":"Aanhoudende preoccupatie met de angst een ernstige ziekte te hebben of te krijgen, ondanks geruststelling.","definition":"<p>Bij de <strong>ziekte-angststoornis</strong> (voorheen hypochondrie) staat de angst om een ernstige aandoening te hebben of te krijgen centraal, meestal met weinig of geen lichamelijke klachten, en zonder dat somatisch onderzoek dit ondersteunt.</p>","image_url":"","wiki_title":"Hypochondriasis","match":"ziekteangststoornis","option_only":true},"obsessief-compulsieve stoornis":{"title":"Obsessief-compulsieve stoornis (OCS)","short":"Stoornis met dwanggedachten (obsessies) en/of dwanghandelingen (compulsies) die veel tijd kosten en lijden veroorzaken.","definition":"<p>De <strong>obsessief-compulsieve stoornis (OCS/OCD)</strong> kenmerkt zich door <em>obsessies</em> (opdringende, angstwekkende gedachten) en <em>compulsies</em> (repeterende handelingen of rituelen om de angst te verminderen). Het corticostriatothalamocorticale circuit speelt een rol in de pathofysiologie.</p>","image_url":"","wiki_title":"","match":"obsessief-compulsieve stoornis","option_only":true},"interpersoonlijke psychotherapie":{"title":"Interpersoonlijke psychotherapie (IPT)","short":"Kortdurende, gestructureerde psychotherapie voor depressie die zich richt op actuele problemen in relaties en rollen (rouw, rolverandering, conflicten, tekorten).","definition":"<p><strong>Interpersoonlijke psychotherapie (IPT)</strong> is een kortdurende (12&ndash;16 sessies) evidence-based behandeling voor depressie. Ze richt zich op het verband tussen depressieve klachten en interpersoonlijke problemen: rouw, rolveranderingen, interpersoonlijke conflicten en interpersoonlijke tekorten. Een sociogram wordt gebruikt om het sociale netwerk in kaart te brengen. Anders dan CGT gebruikt IPT geen dagboeken of huiswerkopdrachten.</p>","image_url":"","wiki_title":"Interpersonal psychotherapy","match":"interpersoonlijke psychotherapie","option_only":true},"schemagerichte psychotherapie":{"title":"Schemagerichte psychotherapie","short":"Op persoonlijkheidsproblematiek gerichte therapie die vroeg ontstane, disfunctionele schema's identificeert en bewerkt.","definition":"<p><strong>Schemagerichte (schema)therapie</strong> richt zich vooral op persoonlijkheidsstoornissen (o.a. borderline). Ze integreert cognitieve gedragstherapie met technieken uit hechtings- en experiëntiële therapie om vroegkinderlijke <em>maladaptieve schema's</em> te doorbreken.</p>","image_url":"","wiki_title":"","match":"schemagerichte psychotherapie","option_only":true},"mirtazapine":{"title":"Mirtazapine","short":"Antidepressivum (NaSSA) met sterk antihistaminerge (H1) werking; de belangrijkste bijwerkingen zijn sedatie en gewichtstoename.","definition":"<p><strong>Mirtazapine</strong> is een noradrenerg en specifiek serotonerg antidepressivum (NaSSA). Door zijn sterke antagonisme van de histamine-H1-receptor veroorzaakt het vooral sedatie en toename van eetlust en gewicht. Het heeft nagenoeg geen anticholinerge werking.</p>","image_url":"","wiki_title":"Mirtazapine","match":"mirtazapine","option_only":true},"globus pallidus, pars externa":{"title":"Globus pallidus pars externa (GPe)","short":"De GPe is onderdeel van de basale kernen en vormt een schakel in de indirecte route; hij remt de nucleus subthalamicus.","definition":"<p>De <strong>globus pallidus pars externa</strong> is het laterale deel van de globus pallidus. Hij ontvangt remmende (GABA-erge) input van het striatum en stuurt zelf remmende projecties naar de nucleus subthalamicus.</p><p>Hij is een kernschakel van de <em>indirecte route</em> van de basale kernen (cortex → striatum → GPe → nucleus subthalamicus → GPi/SNr → thalamus), die beweging per saldo afremt.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus, pars externa","option_only":true},"globus pallidus, pars interna":{"title":"Globus pallidus pars interna (GPi)","short":"De GPi is de belangrijkste uitgangskern van de basale kernen; hij remt (GABA-erg) de motorische thalamus.","definition":"<p>De <strong>globus pallidus pars interna</strong> is samen met de substantia nigra pars reticulata de <em>uitgangskern</em> van de basale kernen. Hij geeft tonisch remmende GABA-erge output naar de motorische kernen van de thalamus.</p><p>De directe route (striatum → GPi) remt de GPi en ontremt zo de thalamus (meer beweging); de indirecte route versterkt via de nucleus subthalamicus juist de remming. De GPi is een doelwit bij diepe hersenstimulatie (o.a. dystonie, Parkinson).</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus, pars interna","option_only":true},"commisura anterior":{"title":"Commissura anterior","short":"Kleine witte-stofbundel die o.a. de temporaalkwabben en reukgebieden verbindt.","definition":"<p>De <b>commissura anterior</b> verbindt onder meer de amygdala en de tractus olfactorius van beide zijden.</p>","image_url":"","wiki_title":"Anterior commissure","match":"commisura anterior","option_only":true},"hallucinatie":{"title":"Hallucinatie","short":"Zintuiglijke waarneming zonder externe prikkel, bijvoorbeeld stemmen horen die er niet zijn; een stoornis van het waarnemen.","definition":"<p>Een <b>hallucinatie</b> is een zintuiglijke waarneming zonder bijbehorende prikkel uit de buitenwereld, zoals het horen van stemmen (auditieve hallucinatie). Het is een stoornis van het <i>waarnemen</i> en komt voor bij psychose.</p>","image_url":"","wiki_title":"Hallucination","match":"hallucinatie","option_only":true},"waan":{"title":"Waan","short":"Onwrikbare, niet met de realiteit overeenkomende overtuiging; een stoornis in de inhoud van het denken.","definition":"<p>Een <b>waan</b> is een onjuiste, onwrikbare overtuiging die niet strookt met de werkelijkheid en niet corrigeerbaar is door logische argumenten. Het is een stoornis van de <i>inhoud van het denken</i> en komt voor bij psychotische stoornissen.</p>","image_url":"","wiki_title":"Delusion","match":"waan","option_only":true},"sociale fobie":{"title":"Sociale fobie","short":"Angststoornis met een aanhoudende, overmatige angst voor situaties waarin men door anderen beoordeeld of gadegeslagen kan worden, met vermijding als gevolg.","definition":"<p><b>Sociale fobie</b> (sociale-angststoornis) is een uitgesproken angst voor sociale of prestatiesituaties waarin iemand negatief beoordeeld kan worden. Dit leidt tot vermijdingsgedrag en somatische angstverschijnselen (blozen, trillen, misselijkheid) in die situaties.</p>","image_url":"","wiki_title":"Social anxiety disorder","match":"sociale fobie","option_only":true},"obsessief compulsieve stoornis":{"title":"Obsessief-compulsieve stoornis (OCS)","short":"Stoornis met dwanggedachten (obsessies) en/of dwanghandelingen (compulsies) die veel tijd kosten en lijden veroorzaken.","definition":"<p>De <strong>obsessief-compulsieve stoornis (OCS/OCD)</strong> kenmerkt zich door <em>obsessies</em> (opdringende, angstwekkende gedachten) en <em>compulsies</em> (repeterende handelingen of rituelen om de angst te verminderen). Het corticostriatothalamocorticale circuit speelt een rol in de pathofysiologie.</p>","image_url":"","wiki_title":"","match":"obsessief compulsieve stoornis","option_only":true},"anergie":{"title":"Anergie","short":"Gebrek aan (fysieke) energie en verhoogde vermoeidheid; veelvoorkomend symptoom bij depressie.","definition":"<p><strong>Anergie</strong> verwijst naar een aanhoudend gebrek aan energie en verhoogde moeheid. Het is een frequent symptoom bij depressieve stoornissen.</p>","image_url":"","wiki_title":"","match":"anergie","option_only":true},"overwaardige denkbeelden":{"title":"Overwaardig denkbeeld","short":"Een overwaardig denkbeeld is een overtuiging die het denken en handelen sterk beheerst, maar niet zo vast en onwrikbaar is als een waan.","definition":"<p>Bij een <strong>overwaardig denkbeeld</strong> kan de persoon twijfel nog enigszins toelaten. Voorbeelden zijn overtuigingen over het eigen uiterlijk (morfodysfore stoornis) of gewicht (anorexia nervosa).</p>","image_url":"","wiki_title":"Overvalued idea","match":"overwaardige denkbeelden|overwaardig denkbeeld","option_only":true},"verlengd qt-interval":{"title":"Verlengd QT-interval","short":"Een verlengd QT-interval op het ECG betekent een vertraagde repolarisatie van de kamers, met een risico op torsade de pointes.","definition":"<p>Oorzaken van <strong>QT-verlenging</strong> zijn erfelijke ionkanaalafwijkingen (lang-QT-syndroom), hypokaliëmie, hypomagnesiëmie, hypocalciëmie en geneesmiddelen (o.a. antipsychotica, citalopram, methadon, macroliden, antiaritmica). Het QT wordt gecorrigeerd voor de hartfrequentie (QTc).</p>","image_url":"","wiki_title":"Long QT syndrome","match":"verlengd qt-interval|qt-verlenging|qtc","option_only":true},"orbitofrontale cortex":{"title":"Orbitofrontale cortex","short":"De orbitofrontale cortex ligt aan de onderkant van de frontaalkwab boven de oogkassen en is betrokken bij beloning, besluitvorming en sociaal gedrag.","definition":"<p>Schade aan de <strong>orbitofrontale cortex</strong> (bijv. door trauma of frontotemporale dementie) geeft ontremming, impulsiviteit, sociaal ongepast gedrag en een veranderde persoonlijkheid, met behouden intelligentie.</p>","image_url":"","wiki_title":"Orbitofrontal cortex","match":"orbitofrontale cortex","option_only":true},"hypersomnia":{"title":"Hypersomnie","short":"Bij hypersomnie is iemand overdag overmatig slaperig, ondanks voldoende nachtslaap.","definition":"<p>Oorzaken zijn o.a. slaapapneu, <strong>narcolepsie</strong> (met slaapaanvallen, kataplexie, hypnagoge hallucinaties en slaapverlamming), idiopathische hypersomnie, depressie en medicatie.</p>","image_url":"","wiki_title":"Hypersomnia","match":"hypersomnia|hypersomnie|narcolepsie","option_only":true},"circadiane slaapstoornis":{"title":"Circadiane ritmestoornis","short":"Bij een circadiane ritmestoornis loopt de biologische klok niet gelijk met het gewenste slaap-waakritme.","definition":"<p>Voorbeelden zijn het <strong>uitgestelde slaapfasesyndroom</strong> (laat inslapen en laat wakker worden, vaak bij adolescenten), ploegendienststoornis en jetlag. Behandeling met lichttherapie in de ochtend en melatonine in de avond.</p>","image_url":"","wiki_title":"Circadian rhythm sleep disorder","match":"circadiane slaapstoornis|circadiane ritmestoornis|delayed sleep phase","option_only":true},"applied tension":{"title":"Applied tension","short":"Applied tension is een techniek waarbij iemand met bloed-injectie-letselfobie de spieren aanspant om de bloeddruk hoog te houden en flauwvallen te voorkomen.","definition":"<p>Bij een <strong>bloed-injectie-letselfobie</strong> daalt de bloeddruk na een eerste stijging (vasovagale reactie), anders dan bij andere fobieën. Applied tension wordt gecombineerd met blootstelling.</p>","image_url":"","wiki_title":"","match":"applied tension","option_only":true},"grimasseren":{"title":"Grimasseren","short":"Grimasseren is het maken van vreemde, onwillekeurig of zinloos ogende gelaatsuitdrukkingen.","definition":"<p><strong>Grimasseren</strong> kan voorkomen bij katatonie en schizofrenie, maar ook bij bewegingsstoornissen zoals tardieve dyskinesie door antipsychotica.</p>","image_url":"","wiki_title":"","match":"grimasseren","option_only":true},"bupropion":{"title":"Bupropion","short":"Bupropion remt de heropname van dopamine en noradrenaline en wordt gebruikt als antidepressivum en bij stoppen met roken.","definition":"<p><strong>Bupropion</strong> geeft weinig seksuele bijwerkingen en gewichtstoename. Het verlaagt de drempel voor epileptische aanvallen en is daarom gecontra-indiceerd bij epilepsie en eetstoornissen.</p>","image_url":"","wiki_title":"Bupropion","match":"bupropion","option_only":true},"competitive memory training":{"title":"Competitive Memory Training (COMET)","short":"COMET is een training die een negatief zelfbeeld verbetert door positieve herinneringen en eigenschappen sterker te laten ‘concurreren’ met negatieve.","definition":"<p>Bij <strong>COMET</strong> worden positieve eigenschappen gekoppeld aan beelden, houding en muziek, zodat ze beter oproepbaar worden. Het wordt gebruikt bij een laag zelfbeeld, depressie en persoonlijkheidsproblematiek.</p>","image_url":"","wiki_title":"","match":"competitive memory training|comet","option_only":true},"dopamine-dysregulatie-stoornis":{"title":"Dopamine-dysregulatiesyndroom","short":"Bij het dopamine-dysregulatiesyndroom gebruiken patiënten met de ziekte van Parkinson dwangmatig meer dopaminerge medicatie dan nodig.","definition":"<p>Dopaminerge middelen, vooral <strong>dopamineagonisten</strong>, kunnen ook impulscontrolestoornissen geven: gokken, koopwoede, hyperseksualiteit en eetbuien. Patiënten en naasten moeten hier vooraf voor worden gewaarschuwd.</p>","image_url":"","wiki_title":"Dopamine dysregulation syndrome","match":"dopamine-dysregulatie-stoornis|dopamine-dysregulatiesyndroom|impulscontrolestoornis","option_only":true},"catecholamine":{"title":"Catecholaminen","short":"Catecholaminen zijn dopamine, noradrenaline en adrenaline, die uit tyrosine worden gemaakt.","definition":"<p>De aanmaak verloopt van tyrosine via L-DOPA naar dopamine, noradrenaline en (in het bijniermerg) adrenaline. Ze worden afgebroken door MAO en COMT. Een feochromocytoom maakt een overmaat aan <strong>catecholaminen</strong>, aantoonbaar via metanefrines.</p>","image_url":"","wiki_title":"Catecholamine","match":"catecholamine|catecholaminen","option_only":true},"paniekstoornis met agorafobie":{"title":"Paniekstoornis en agorafobie","short":"Bij een paniekstoornis zijn er onverwachte paniekaanvallen en aanhoudende angst voor nieuwe aanvallen; bij agorafobie vermijdt iemand situaties waaruit ontsnappen moeilijk is.","definition":"<p>Een <strong>paniekaanval</strong> geeft hartkloppingen, benauwdheid, duizeligheid en angst om dood te gaan of gek te worden. Behandeling: cognitieve gedragstherapie met interoceptieve en situationele blootstelling, eventueel een SSRI.</p>","image_url":"","wiki_title":"Panic disorder","match":"paniekstoornis met agorafobie|paniekstoornis|agorafobie","option_only":true},"nucleus ruber":{"title":"Nucleus ruber","short":"De nucleus ruber is een kern in het mesencephalon die betrokken is bij motoriek en ontvangt input uit het cerebellum.","definition":"<p>Een laesie rond de <strong>nucleus ruber</strong> kan een grove, langzame tremor geven (rubrale of Holmes-tremor), soms met een oculomotoriusparese aan dezelfde kant (syndroom van Benedikt).</p>","image_url":"","wiki_title":"Red nucleus","match":"nucleus ruber|rode kern","option_only":true},"incoherent denken":{"title":"Formele denkstoornissen","short":"Formele denkstoornissen zijn stoornissen in het tempo of de samenhang van het denken, zoals incoherentie, gedachtenvlucht en zijsporigheid.","definition":"<p>Bij <strong>incoherentie</strong> is de samenhang tussen zinnen en woorden verloren (‘woordsalade’), wat past bij een psychose of een delier. <strong>Gedachtenvlucht</strong> (versneld denken met snelle overgangen tussen onderwerpen) past bij een manie.</p>","image_url":"","wiki_title":"Thought disorder","match":"incoherent denken|incoherentie|gedachtenvlucht|desorganisatie","option_only":true},"propanolol":{"title":"Propranolol","short":"Propranolol is een niet-selectieve bètablokker, o.a. gebruikt bij portale hypertensie, migraineprofylaxe, essentiële tremor en de lichamelijke kant van angst.","definition":"<p>Door blokkade van β1 en β2 verlaagt <strong>propranolol</strong> de hartminuutvolume en vernauwt het de splanchnische vaten, wat de poortaderdruk verlaagt. Het kan bronchospasmen geven bij astma en de symptomen van een hypoglykemie maskeren.</p>","image_url":"","wiki_title":"Propranolol","match":"propanolol|propranolol","option_only":true},"vitamine b12 suppletie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b12 suppletie","option_only":true},"verlenging van qtc tijd":{"title":"Verlengd QT-interval","short":"Een verlengd QT-interval op het ECG betekent een vertraagde repolarisatie van de kamers, met een risico op torsade de pointes.","definition":"<p>Oorzaken van <strong>QT-verlenging</strong> zijn erfelijke ionkanaalafwijkingen (lang-QT-syndroom), hypokaliëmie, hypomagnesiëmie, hypocalciëmie en geneesmiddelen (o.a. antipsychotica, citalopram, methadon, macroliden, antiaritmica). Het QT wordt gecorrigeerd voor de hartfrequentie (QTc).</p>","image_url":"","wiki_title":"Long QT syndrome","match":"verlenging van qtc tijd","option_only":true},"ziekeangststoornis":{"title":"Ziekte-angststoornis","short":"Aanhoudende preoccupatie met de angst een ernstige ziekte te hebben of te krijgen, ondanks geruststelling.","definition":"<p>Bij de <strong>ziekte-angststoornis</strong> (voorheen hypochondrie) staat de angst om een ernstige aandoening te hebben of te krijgen centraal, meestal met weinig of geen lichamelijke klachten, en zonder dat somatisch onderzoek dit ondersteunt.</p>","image_url":"","wiki_title":"Hypochondriasis","match":"ziekeangststoornis","option_only":true},"gabapentin":{"title":"Pregabaline","short":"Pregabaline is een middel tegen neuropathische pijn, epilepsie en gegeneraliseerde angst; het remt calciumkanalen in zenuwuiteinden.","definition":"<p><strong>Pregabaline</strong> en gabapentine binden aan de α2δ-subeenheid van calciumkanalen en verminderen de afgifte van prikkelende neurotransmitters. Bijwerkingen: sufheid, duizeligheid en oedeem; er is risico op misbruik en afhankelijkheid. Bij nierfunctiestoornis is een lagere dosis nodig.</p>","image_url":"","wiki_title":"Pregabalin","match":"gabapentin","option_only":true},"de ziekte van parkinson":{"title":"Ziekte van Parkinson","short":"De ziekte van Parkinson is een neurodegeneratieve ziekte door verlies van dopaminerge neuronen in de substantia nigra, met rusttremor, bradykinesie en rigiditeit.","definition":"<p>Bij de <strong>ziekte van Parkinson</strong> gaan dopaminerge neuronen in de substantia nigra pars compacta verloren, met Lewy-lichaampjes (alfa-synucleïne). Kernsymptomen zijn bradykinesie, rigiditeit, rusttremor en later houdingsinstabiliteit; vaak ook niet-motorische klachten zoals reukverlies, obstipatie, depressie en slaapstoornissen. Behandeling met levodopa en dopamine-agonisten.</p>","image_url":"","wiki_title":"Parkinson's disease","match":"de ziekte van parkinson","option_only":true},"alzheimer’s dementie":{"title":"Ziekte van Alzheimer","short":"De ziekte van Alzheimer is de meest voorkomende oorzaak van dementie, met geleidelijk verlies van vooral het episodisch geheugen.","definition":"<p>Bij <strong>Alzheimer</strong> stapelen zich amyloïdplaques en neurofibrillaire tangles (tau) op, met verlies van neuronen, beginnend in de mediale temporaalkwab. Later volgen problemen met taal, oriëntatie, uitvoerende functies en gedrag. Cholinesteraseremmers en memantine geven een bescheiden symptomatisch effect.</p>","image_url":"","wiki_title":"Alzheimer's disease","match":"alzheimer’s dementie","option_only":true},"sociale angststoornis":{"title":"Sociale-angststoornis","short":"Bij een sociale-angststoornis is er een sterke angst om door anderen negatief beoordeeld te worden, met vermijding van sociale situaties.","definition":"<p>De <strong>sociale-angststoornis</strong> begint meestal in de adolescentie. Er zijn lichamelijke klachten zoals blozen, trillen en zweten. Behandeling: cognitieve gedragstherapie met blootstelling, eventueel een SSRI.</p>","image_url":"","wiki_title":"Social anxiety disorder","match":"sociale angststoornis|sociale-angststoornis|sociale fobie","option_only":true},"normoverschrijdend-gedragsstoornis":{"title":"Normoverschrijdend-gedragsstoornis","short":"Bij een normoverschrijdend-gedragsstoornis schendt een kind of jongere herhaaldelijk de rechten van anderen en belangrijke sociale normen.","definition":"<p>Voorbeelden zijn agressie tegen mensen of dieren, vernieling, liegen, stelen en ernstige regelovertredingen. Begint het vóór de leeftijd van 10 jaar, dan is de prognose ongunstiger; het kan overgaan in een antisociale persoonlijkheidsstoornis op volwassen leeftijd.</p>","image_url":"","wiki_title":"Conduct disorder","match":"normoverschrijdend-gedragsstoornis|normoverschrijdend gedragsstoornis|conduct disorder","option_only":true},"naloxon":{"title":"Naloxon","short":"Naloxon is een opioïdantagonist die een opiaatintoxicatie snel opheft.","definition":"<p><strong>Naloxon</strong> werkt korter dan de meeste opioïden, waardoor de ademhalingsdepressie kan terugkeren; herhaalde toediening of een infuus kan nodig zijn. Bij opiaatafhankelijke patiënten kan het een acute onttrekking uitlokken.</p>","image_url":"","wiki_title":"Naloxone","match":"naloxon|nalexon","option_only":true},"delier":{"title":"Delier","short":"Een delier is een acute, wisselende stoornis van aandacht en bewustzijn, met verwardheid, door een lichamelijke oorzaak.","definition":"<p>Een <strong>delier</strong> komt veel voor bij ouderen in het ziekenhuis, na operaties en bij infecties, medicatie, onttrekking (alcohol) en metabole stoornissen. Er is een hypoactieve en een hyperactieve vorm. Behandeling: de oorzaak behandelen, oriëntatie bieden, en zo nodig haloperidol.</p>","image_url":"","wiki_title":"Delirium","match":"delier|een delier|delirium","option_only":true},"huisstofmijt":{"title":"Huisstofmijt","short":"De huisstofmijt is een klein spinachtig diertje in beddengoed en stof; allergie voor zijn uitwerpselen is een belangrijke oorzaak van allergisch astma en rhinitis.","definition":"<p>Klachten van een <strong>huisstofmijtallergie</strong> zijn vaak het hele jaar aanwezig en 's ochtends erger. De diagnose wordt gesteld met een huidpriktest of specifiek IgE. Hoesjes om het matras hebben weinig effect; immunotherapie kan helpen.</p>","image_url":"","wiki_title":"House dust mite","match":"huisstofmijt|huisstofmijt allergie","option_only":true},"somatische symptoomstoornis":{"title":"Somatisatie","short":"Somatisatie is de neiging om psychische spanning te ervaren en te uiten als lichamelijke klachten.","definition":"<p>Bij een <strong>somatisch-symptoomstoornis</strong> zijn er lichamelijke klachten die veel zorgen, gedachten en gedrag oproepen en het functioneren beperken, ongeacht of er een medische verklaring is. Behandeling richt zich op uitleg, het doorbreken van vicieuze cirkels en geleidelijk opbouwen van activiteiten, vaak met cognitieve gedragstherapie.</p>","image_url":"","wiki_title":"Somatic symptom disorder","match":"somatische symptoomstoornis","option_only":true},"een ssri":{"title":"SSRI","short":"Selectieve serotonineheropnameremmer; antidepressivum dat ook een trombocytopathie kan veroorzaken.","definition":"<p>Een <b>SSRI</b> (selectieve serotonineheropnameremmer) is een veelgebruikt antidepressivum. SSRI’s remmen de heropname van serotonine, ook in de bloedplaatjes, waardoor een <b>trombocytopathie</b> ontstaat en het risico op maag-/bloedingscomplicaties toeneemt, zeker samen met NSAIDs.</p>","image_url":"","wiki_title":"Selective serotonin reuptake inhibitor","match":"een ssri","option_only":true},"ssri-medicatie":{"title":"SSRI","short":"Selectieve serotonineheropnameremmer; antidepressivum dat ook een trombocytopathie kan veroorzaken.","definition":"<p>Een <b>SSRI</b> (selectieve serotonineheropnameremmer) is een veelgebruikt antidepressivum. SSRI’s remmen de heropname van serotonine, ook in de bloedplaatjes, waardoor een <b>trombocytopathie</b> ontstaat en het risico op maag-/bloedingscomplicaties toeneemt, zeker samen met NSAIDs.</p>","image_url":"","wiki_title":"Selective serotonin reuptake inhibitor","match":"ssri-medicatie","option_only":true},"een tricyclisch antidepressivum":{"title":"Tricyclische antidepressiva","short":"Tricyclische antidepressiva remmen de heropname van noradrenaline en serotonine en hebben veel anticholinerge bijwerkingen.","definition":"<p><strong>TCA's</strong> (zoals amitriptyline, nortriptyline, clomipramine) worden gebruikt bij depressie en in lage dosis bij neuropathische pijn. Bijwerkingen: droge mond, obstipatie, urineretentie, sufheid, orthostatische hypotensie en gewichtstoename. Bij overdosering zijn ze gevaarlijk door natriumkanaalblokkade (breed QRS, aritmieën) en insulten.</p>","image_url":"","wiki_title":"Tricyclic antidepressant","match":"een tricyclisch antidepressivum","option_only":true},"een klassieke mao-remmer":{"title":"Monoamineoxidase (MAO)","short":"Monoamineoxidase is een enzym in de buitenmembraan van mitochondriën dat monoamines zoals serotonine, noradrenaline en dopamine afbreekt.","definition":"<p>Er zijn twee vormen: <strong>MAO-A</strong> (vooral serotonine en noradrenaline, ook tyramine in de darm) en <strong>MAO-B</strong> (vooral dopamine). MAO-remmers worden gebruikt bij depressie (MAO-A) en de ziekte van Parkinson (MAO-B, bijv. selegiline, rasagiline). Bij niet-selectieve remmers kan tyraminerijk voedsel (oude kaas) een hypertensieve crisis geven.</p>","image_url":"","wiki_title":"Monoamine oxidase","match":"een klassieke mao-remmer","option_only":true},"sociale-angststoornis":{"title":"Sociale-angststoornis","short":"Bij een sociale-angststoornis is er een sterke angst om door anderen negatief beoordeeld te worden, met vermijding van sociale situaties.","definition":"<p>De <strong>sociale-angststoornis</strong> begint meestal in de adolescentie. Er zijn lichamelijke klachten zoals blozen, trillen en zweten. Behandeling: cognitieve gedragstherapie met blootstelling, eventueel een SSRI.</p>","image_url":"","wiki_title":"Social anxiety disorder","match":"sociale-angststoornis","option_only":true},"normoverschrijdend gedragsstoornis":{"title":"Normoverschrijdend-gedragsstoornis","short":"Bij een normoverschrijdend-gedragsstoornis schendt een kind of jongere herhaaldelijk de rechten van anderen en belangrijke sociale normen.","definition":"<p>Voorbeelden zijn agressie tegen mensen of dieren, vernieling, liegen, stelen en ernstige regelovertredingen. Begint het vóór de leeftijd van 10 jaar, dan is de prognose ongunstiger; het kan overgaan in een antisociale persoonlijkheidsstoornis op volwassen leeftijd.</p>","image_url":"","wiki_title":"Conduct disorder","match":"normoverschrijdend gedragsstoornis","option_only":true},"nalexon":{"title":"Naloxon","short":"Naloxon is een opioïdantagonist die een opiaatintoxicatie snel opheft.","definition":"<p><strong>Naloxon</strong> werkt korter dan de meeste opioïden, waardoor de ademhalingsdepressie kan terugkeren; herhaalde toediening of een infuus kan nodig zijn. Bij opiaatafhankelijke patiënten kan het een acute onttrekking uitlokken.</p>","image_url":"","wiki_title":"Naloxone","match":"nalexon","option_only":true},"een delier":{"title":"Delier","short":"Een delier is een acute, wisselende stoornis van aandacht en bewustzijn, met verwardheid, door een lichamelijke oorzaak.","definition":"<p>Een <strong>delier</strong> komt veel voor bij ouderen in het ziekenhuis, na operaties en bij infecties, medicatie, onttrekking (alcohol) en metabole stoornissen. Er is een hypoactieve en een hyperactieve vorm. Behandeling: de oorzaak behandelen, oriëntatie bieden, en zo nodig haloperidol.</p>","image_url":"","wiki_title":"Delirium","match":"een delier","option_only":true},"huisstofmijt allergie":{"title":"Huisstofmijt","short":"De huisstofmijt is een klein spinachtig diertje in beddengoed en stof; allergie voor zijn uitwerpselen is een belangrijke oorzaak van allergisch astma en rhinitis.","definition":"<p>Klachten van een <strong>huisstofmijtallergie</strong> zijn vaak het hele jaar aanwezig en 's ochtends erger. De diagnose wordt gesteld met een huidpriktest of specifiek IgE. Hoesjes om het matras hebben weinig effect; immunotherapie kan helpen.</p>","image_url":"","wiki_title":"House dust mite","match":"huisstofmijt allergie","option_only":true},"incongruent affect":{"title":"Affect (psychiatrisch onderzoek)","short":"Het affect is de zichtbare uiting van de stemming; het wordt beoordeeld op modulatie (variatie), stabiliteit en congruentie met de inhoud van het gesprek.","definition":"<p>Bij een <strong>vlak affect</strong> is er weinig variatie, bij een <strong>labiel affect</strong> wisselt het snel en heftig, en bij een <strong>incongruent affect</strong> past het niet bij wat iemand vertelt (bijv. lachen bij iets verdrietigs), wat bij schizofrenie voorkomt. Een goed modulerend affect is normaal.</p>","image_url":"","wiki_title":"Affect (psychology)","match":"incongruent affect|modulerend affect|vlak affect|labiel affect","option_only":true},"dysforie":{"title":"Dysforie","short":"Dysforie is een sombere, prikkelbare of ontstemde stemming.","definition":"<p><strong>Dysforie</strong> komt voor bij depressie, persoonlijkheidsstoornissen, onthouding en een gemengde episode bij de bipolaire stoornis. Het is iets anders dan genderdysforie, de last van een mismatch tussen ervaren gender en toegewezen geslacht.</p>","image_url":"","wiki_title":"Dysphoria","match":"dysforie|dysfore stemming","option_only":true},"hypomanische episode":{"title":"Hypomanie","short":"Een hypomane episode is een periode van minstens vier dagen met een verhoogde of prikkelbare stemming en meer energie, zonder ernstige ontregeling van het functioneren.","definition":"<p>Bij een <strong>hypomanie</strong> zijn er geen psychotische kenmerken en is er geen opname nodig; anders is het een manie. Een depressie met minstens één hypomanie heet een bipolaire II-stoornis.</p>","image_url":"","wiki_title":"Hypomania","match":"hypomanische episode|hypomanie","option_only":true},"interoceptieve angst":{"title":"Interoceptieve angst en blootstelling","short":"Interoceptieve angst is angst voor lichamelijke sensaties, zoals hartkloppingen of duizeligheid, die bij een paniekstoornis als gevaarlijk worden geïnterpreteerd.","definition":"<p>Bij <strong>interoceptieve blootstelling</strong> wekt de patiënt deze sensaties bewust op (bijv. door snel te ademen of rond te draaien), om te leren dat ze onschuldig zijn.</p>","image_url":"","wiki_title":"","match":"interoceptieve angst|interoceptieve blootstelling","option_only":true},"chronische slapeloosheid":{"title":"Insomnie","short":"Insomnie is moeite met in- of doorslapen of te vroeg wakker worden, minstens drie nachten per week gedurende drie maanden, met klachten overdag.","definition":"<p>De eerste keus bij <strong>chronische insomnie</strong> is CGT voor insomnie (slaaprestrictie, stimuluscontrole, slaaphygiëne, cognitieve technieken). Slaapmiddelen zijn alleen kortdurend zinvol, vanwege gewenning, afhankelijkheid en valrisico.</p>","image_url":"","wiki_title":"Insomnia","match":"chronische slapeloosheid|insomnie|slapeloosheid","option_only":true},"selectieve aandacht":{"title":"Selectieve aandacht","short":"Selectieve aandacht is het richten van de aandacht op bepaalde prikkels en het negeren van andere.","definition":"<p>Bij angststoornissen is er vaak een <strong>aandachtsbias</strong>: dreigende prikkels worden sneller opgemerkt, wat de angst in stand houdt. Bij hypochondrie wordt de aandacht vaak op lichamelijke sensaties gericht.</p>","image_url":"","wiki_title":"Attentional bias","match":"selectieve aandacht|aandachtsbias","option_only":true},"anabole steroïden":{"title":"Anabole steroïden","short":"Anabole steroïden zijn synthetische varianten van testosteron die spiergroei bevorderen.","definition":"<p>Misbruik van <strong>anabole steroïden</strong> geeft o.a. acne, testisatrofie en onvruchtbaarheid, gynaecomastie, leverschade, een ongunstig cholesterolprofiel, polycytemie, hart- en vaatziekten en stemmingsstoornissen (agressie, depressie bij stoppen).</p>","image_url":"","wiki_title":"Anabolic steroid","match":"anabole steroïden|anabolica","option_only":true},"hepatotoxiciteit":{"title":"Hepatotoxiciteit","short":"Hepatotoxiciteit is leverschade door geneesmiddelen of andere stoffen.","definition":"<p>Bekende oorzaken zijn <strong>paracetamol</strong> (dosisafhankelijk), amoxicilline/clavulaanzuur, isoniazide, methotrexaat, valproaat, statines (zelden) en kruidenmiddelen. Het patroon kan hepatocellulair (hoog ALAT), cholestatisch (hoog AF) of gemengd zijn.</p>","image_url":"","wiki_title":"Hepatotoxicity","match":"hepatotoxiciteit|drug-induced liver injury|dili","option_only":true},"lood in het drinkwater":{"title":"Loodvergiftiging","short":"Lood is een giftig zwaar metaal; bij kinderen geeft blootstelling (oude verf, loden waterleidingen) al bij lage spiegels ontwikkelingsachterstand.","definition":"<p>Bij <strong>loodvergiftiging</strong> zijn er buikpijn, obstipatie, anemie met basofiele stippeling, neuropathie (dropshand) en een blauwe lijn langs het tandvlees. Lood remt de heemsynthese. Behandeling: blootstelling stoppen, eventueel chelatietherapie.</p>","image_url":"","wiki_title":"Lead poisoning","match":"lood in het drinkwater|loodvergiftiging|lood","option_only":true},"traumatherapie":{"title":"Traumagerichte therapie","short":"Traumagerichte therapieën bij PTSS zijn o.a. EMDR, imaginaire exposure en traumagerichte cognitieve gedragstherapie.","definition":"<p>Bij <strong>EMDR</strong> denkt de patiënt aan de traumatische herinnering terwijl de werkgeheugenbelasting wordt verhoogd (oogbewegingen, geluiden), waardoor de herinnering minder emotioneel geladen wordt. Medicatie (SSRI) is een tweede keus.</p>","image_url":"","wiki_title":"Eye movement desensitization and reprocessing","match":"traumatherapie|emdr|imaginaire exposure","option_only":true},"relatietherapie":{"title":"Systeem- en relatietherapie","short":"Bij relatie- en systeemtherapie wordt niet alleen de patiënt, maar het hele systeem (partner, gezin) bij de behandeling betrokken.","definition":"<p><strong>Systeemtherapie</strong> wordt gebruikt bij relatieproblemen, problemen in gezinnen met kinderen en jongeren, en als aanvulling bij o.a. eetstoornissen en verslaving.</p>","image_url":"","wiki_title":"Family therapy","match":"relatietherapie|systeemtherapie|gezinstherapie","option_only":true},"modulerend affect":{"title":"Affect (psychiatrisch onderzoek)","short":"Het affect is de zichtbare uiting van de stemming; het wordt beoordeeld op modulatie (variatie), stabiliteit en congruentie met de inhoud van het gesprek.","definition":"<p>Bij een <strong>vlak affect</strong> is er weinig variatie, bij een <strong>labiel affect</strong> wisselt het snel en heftig, en bij een <strong>incongruent affect</strong> past het niet bij wat iemand vertelt (bijv. lachen bij iets verdrietigs), wat bij schizofrenie voorkomt. Een goed modulerend affect is normaal.</p>","image_url":"","wiki_title":"Affect (psychology)","match":"modulerend affect","option_only":true},"cognitieve therapie":{"title":"Cognitieve gedragstherapie","short":"Cognitieve gedragstherapie richt zich op het veranderen van niet-helpende gedachten en gedrag.","definition":"<p>In <strong>cognitieve gedragstherapie</strong> leert iemand automatische negatieve gedachten te herkennen en te toetsen, en nieuw gedrag uit te proberen (bijv. exposure bij angst, activering bij depressie). Het is een kortdurende, gestructureerde therapie met bewezen effect bij o.a. depressie, angststoornissen, OCS, slapeloosheid en eetstoornissen.</p>","image_url":"","wiki_title":"Cognitive behavioral therapy","match":"cognitieve therapie","option_only":true},"cgt voor depressie":{"title":"Cognitieve gedragstherapie","short":"Cognitieve gedragstherapie richt zich op het veranderen van niet-helpende gedachten en gedrag.","definition":"<p>In <strong>cognitieve gedragstherapie</strong> leert iemand automatische negatieve gedachten te herkennen en te toetsen, en nieuw gedrag uit te proberen (bijv. exposure bij angst, activering bij depressie). Het is een kortdurende, gestructureerde therapie met bewezen effect bij o.a. depressie, angststoornissen, OCS, slapeloosheid en eetstoornissen.</p>","image_url":"","wiki_title":"Cognitive behavioral therapy","match":"cgt voor depressie","option_only":true},"cognitieve gedragstherapie voor patiënt":{"title":"Cognitieve gedragstherapie","short":"Cognitieve gedragstherapie richt zich op het veranderen van niet-helpende gedachten en gedrag.","definition":"<p>In <strong>cognitieve gedragstherapie</strong> leert iemand automatische negatieve gedachten te herkennen en te toetsen, en nieuw gedrag uit te proberen (bijv. exposure bij angst, activering bij depressie). Het is een kortdurende, gestructureerde therapie met bewezen effect bij o.a. depressie, angststoornissen, OCS, slapeloosheid en eetstoornissen.</p>","image_url":"","wiki_title":"Cognitive behavioral therapy","match":"cognitieve gedragstherapie voor patiënt","option_only":true},"geagiteerde depressie":{"title":"atypische depressie","short":"Subtype depressie met stemmingsreactiviteit en ‘omgekeerde’ vegetatieve symptomen: veel slapen, toegenomen eetlust/gewicht, loodzwaar gevoel en gevoeligheid voor afwijzing.","definition":"<p>De <strong>atypische depressie</strong> onderscheidt zich door stemmingsreactiviteit (opklaren bij positieve gebeurtenissen) en ‘omgekeerde’ vegetatieve kenmerken: hypersomnie, toegenomen eetlust en gewicht, loodzwaar gevoel in de ledematen en een langdurige gevoeligheid voor interpersoonlijke afwijzing. Klassieke MAO-remmers zijn hierbij relatief effectief.</p>","image_url":"","wiki_title":"Atypical depression","match":"geagiteerde depressie","option_only":true},"thought-action fusion":{"title":"Thought-action fusion","short":"Bij thought-action fusion gelooft iemand dat het denken aan iets de kans vergroot dat het gebeurt, of moreel gelijkstaat aan het doen ervan.","definition":"<p><strong>Thought-action fusion</strong> komt vooral voor bij de obsessieve-compulsieve stoornis en houdt dwanghandelingen in stand. Obsessies over symmetrie en ordening zijn een ander veelvoorkomend thema bij OCS.</p>","image_url":"","wiki_title":"","match":"thought-action fusion|symmetrie obsessies","option_only":true},"verhoogd prolactine":{"title":"Hyperprolactinemie","short":"Hyperprolactinemie is een verhoogd prolactine in het bloed, met galactorroe, cyclusstoornissen en een verminderd libido.","definition":"<p>Oorzaken zijn een <strong>prolactinoom</strong>, antipsychotica en andere dopamineantagonisten (metoclopramide), hypothyreoïdie, zwangerschap en compressie van de hypofysesteel. Behandeling van een prolactinoom met dopamineagonisten (cabergoline).</p>","image_url":"","wiki_title":"Hyperprolactinaemia","match":"verhoogd prolactine|hyperprolactinemie|prolactinoom","option_only":true},"antihistaminerge bijwerkingen":{"title":"Receptorprofiel en bijwerkingen van psychofarmaca","short":"Veel psychofarmaca blokkeren naast hun doelwit ook andere receptoren, wat voorspelbare bijwerkingen geeft.","definition":"<p><strong>Antihistaminerg</strong>: sufheid en gewichtstoename. <strong>Anti-α1-adrenerg</strong>: orthostatische hypotensie en duizeligheid. <strong>Antidopaminerg</strong>: extrapiramidale verschijnselen en hyperprolactinemie.</p>","image_url":"","wiki_title":"","match":"antihistaminerge bijwerkingen|antidopaminerge bijwerkingen|antinoradrenerge bijwerkingen|anticholinerge bijwerkingen","option_only":true}};
